import { motion } from 'framer-motion'
import { ArrowLeft } from 'lucide-react'

const DialectRescueGuide = ({ onBack }) => {
  return (
    <div className="min-h-screen bg-bg pt-12 pb-16">
      {/* Header */}
      <div className="px-4 pt-4 pb-4 flex items-center justify-center relative bg-white">
        <motion.button
          whileTap={{ scale: 0.9 }}
          onClick={onBack}
          className="w-8 h-8 bg-white rounded-full flex items-center justify-center shadow-card absolute left-4"
        >
          <ArrowLeft size={20} className="text-gray-600" />
        </motion.button>
        <h1 className="text-lg font-semibold text-gray-800">方言呼救录制说明</h1>
      </div>

      {/* Content */}
      <div className="px-4 py-6 space-y-6">
        {/* 介绍 */}
        <div className="bg-white rounded-2xl p-5 shadow-sm">
          <p className="text-sm text-gray-600 leading-relaxed">
            除了普通话「救命」外，设备也支持使用方言进行呼救哦
          </p>
        </div>

        {/* 方言设置流程 */}
        <div className="bg-white rounded-2xl p-5 shadow-sm">
          <h2 className="text-base font-semibold text-gray-800 mb-4">👉 方言设置流程：</h2>
          
          <div className="space-y-4">
            <StepItem step="1" title="开启录制" desc="在设备联网状态下，对设备说：「开始录制方言」" />
            <StepItem step="2" title="首次录制" desc="听到设备提示「请在安静环境下录制方言」后，说出您想设置的「方言呼救词」" />
            <StepItem step="3" title="二次录制" desc="听到设备提示「请再说一遍」后，再次说出「方言呼救词」" />
            <StepItem step="4" title="设置成功" desc="设备提示「方言录入成功，可稍后尝试」时，即录入成功。此时喊3声方言呼救词，即可触发设备告警" />
          </div>
        </div>

        {/* 其他说明 */}
        <div className="bg-white rounded-2xl p-5 shadow-sm">
          <h2 className="text-base font-semibold text-gray-800 mb-4">💡 其他：</h2>
          
          <div className="space-y-4">
            <div>
              <h3 className="text-sm font-medium text-gray-700 mb-2">录制失败</h3>
              <p className="text-sm text-gray-600 leading-relaxed">
                受环境噪音影响，方言可能会录制失败。听到「方言录入失败，请重新录制」时，对设备说：「开始录制方言」，重新进行录制即可。
              </p>
            </div>

            <div className="border-t border-gray-100 pt-4">
              <h3 className="text-sm font-medium text-gray-700 mb-2">删除方言</h3>
              <p className="text-sm text-gray-600 leading-relaxed">
                录制新的方言呼救词时，需先删除已有方言。对设备说「删除方言」，听到「方言已删除」时，即删除成功。此时再说「开始录制方言」，即可开始录制新的方言呼救词。
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

const StepItem = ({ step, title, desc }) => {
  return (
    <div className="flex gap-3">
      <div className="flex-shrink-0 w-6 h-6 rounded-full bg-primary/10 flex items-center justify-center">
        <span className="text-xs font-semibold text-primary">{step}</span>
      </div>
      <div className="flex-1">
        <h3 className="text-sm font-medium text-gray-800 mb-1">{title}</h3>
        <p className="text-sm text-gray-600 leading-relaxed">{desc}</p>
      </div>
    </div>
  )
}

export default DialectRescueGuide