import { useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import {
  ArrowLeft,
  Volume2,
  Mic,
  MousePointerClick,
  Wifi,
  Settings,
  Trash2,
  Edit3,
  Check,
  X,
  Phone,
} from 'lucide-react'
import Card from '../components/common/Card'
import Drawer from '../components/common/Drawer'

const DeviceManagement = ({ device, onBack }) => {
  const [deviceName, setDeviceName] = useState(device?.location || '未知位置')
  const [isEditingName, setIsEditingName] = useState(false)
  const [volume, setVolume] = useState(device?.volume || 50)
  const [patEnabled, setPatEnabled] = useState(device?.patEnabled || false)
  const [showVolumeDrawer, setShowVolumeDrawer] = useState(false)
  const [showCallDialog, setShowCallDialog] = useState(false)
  const [showReNetworkDialog, setShowReNetworkDialog] = useState(false)
  const [showUnbindDialog, setShowUnbindDialog] = useState(false)

  const getDeviceIcon = (type) => {
    switch (type) {
      case 'sensor':
        return <Volume2 size={40} className="text-primary" />
      case 'radar':
        return <Wifi size={40} className="text-primary" />
      case 'bed':
        return <MousePointerClick size={40} className="text-primary" />
      default:
        return <Settings size={40} className="text-primary" />
    }
  }

  const handleSaveName = () => {
    setIsEditingName(false)
  }

  const handleUnbindConfirm = () => {
    setShowUnbindDialog(false)
    onBack()
  }

  const handleReNetworkConfirm = () => {
    setShowReNetworkDialog(false)
  }

  return (
    <div className="min-h-screen bg-bg pt-12 pb-16">
      {/* Header - 居中显示 */}
      <div className="px-4 pt-4 pb-4 flex items-center justify-center relative">
        <motion.button
          whileTap={{ scale: 0.9 }}
          onClick={onBack}
          className="w-8 h-8 bg-white rounded-full flex items-center justify-center shadow-card absolute left-4"
        >
          <ArrowLeft size={20} className="text-gray-600" />
        </motion.button>
        <h1 className="text-lg font-semibold text-gray-800">设备管理</h1>
      </div>

      {/* Device Illustration & Info */}
      <div className="px-4 mb-4">
        <Card className="p-6 text-center">
          <div className="w-20 h-20 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-4">
            {getDeviceIcon(device?.type)}
          </div>

          {/* Device Name - Editable */}
          <div className="mb-3">
            {isEditingName ? (
              <div className="flex items-center justify-center gap-2">
                <input
                  type="text"
                  value={deviceName}
                  onChange={(e) => setDeviceName(e.target.value)}
                  className="text-center text-lg font-medium text-gray-800 border-b border-gray-300 focus:outline-none focus:border-primary"
                  autoFocus
                />
                <motion.button
                  whileTap={{ scale: 0.9 }}
                  onClick={handleSaveName}
                  className="text-primary"
                >
                  <Check size={18} />
                </motion.button>
                <motion.button
                  whileTap={{ scale: 0.9 }}
                  onClick={() => {
                    setIsEditingName(false)
                    setDeviceName(device?.location || '未知位置')
                  }}
                  className="text-gray-400"
                >
                  <X size={18} />
                </motion.button>
              </div>
            ) : (
              <div className="flex items-center justify-center gap-2">
                <p className="text-lg font-medium text-gray-800">{deviceName}</p>
                <motion.button
                  whileTap={{ scale: 0.9 }}
                  onClick={() => setIsEditingName(true)}
                  className="text-gray-400"
                >
                  <Edit3 size={16} />
                </motion.button>
              </div>
            )}
          </div>

          {/* Device Status */}
          <div className="mb-2">
            <span className={`text-xs px-3 py-1 rounded-full ${
              device?.status === 'online'
                ? 'bg-green-100 text-green-600'
                : 'bg-gray-100 text-gray-500'
            }`}>
              {device?.status === 'online' ? '在线' : '离线'}
            </span>
          </div>
        </Card>
      </div>

      {/* Device Settings */}
      <div className="px-4 space-y-3">
        {/* Volume Control */}
        <Card className="p-4">
          <motion.button
            whileTap={{ scale: 0.98 }}
            onClick={() => setShowVolumeDrawer(true)}
            className="w-full flex items-center justify-between"
          >
            <div className="flex items-center gap-3">
              <Volume2 size={20} className="text-gray-600" />
              <span className="text-sm text-gray-700">音量调节</span>
            </div>
            <div className="flex items-center gap-2">
              <span className="text-sm text-gray-500">{volume}</span>
            </div>
          </motion.button>
        </Card>

        {/* Two-way Intercom */}
        <Card className="p-4">
          <motion.button
            whileTap={{ scale: 0.98 }}
            onClick={() => setShowCallDialog(true)}
            className="w-full flex items-center justify-between"
          >
            <div className="flex items-center gap-3">
              <Mic size={20} className="text-gray-600" />
              <span className="text-sm text-gray-700">双向对讲</span>
            </div>
          </motion.button>
        </Card>

        {/* Pat Recognition */}
        <Card className="p-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <MousePointerClick size={20} className="text-gray-600" />
              <span className="text-sm text-gray-700">拍打识别</span>
            </div>
            {/* 右侧开关 */}
            <motion.button
              whileTap={{ scale: 0.9 }}
              onClick={() => setPatEnabled(!patEnabled)}
              className={`relative inline-flex h-6 w-10 items-center rounded-full transition-colors ${
                patEnabled ? 'bg-primary' : 'bg-gray-300'
              }`}
            >
              <span className={`inline-block h-5 w-5 transform rounded-full bg-white transition-transform ${
                patEnabled ? 'translate-x-5' : 'translate-x-1'
              }`} />
            </motion.button>
          </div>
        </Card>

        {/* Re-network */}
        <Card className="p-4">
          <motion.button
            whileTap={{ scale: 0.98 }}
            onClick={() => setShowReNetworkDialog(true)}
            className="w-full flex items-center justify-between"
          >
            <div className="flex items-center gap-3">
              <Settings size={20} className="text-gray-600" />
              <span className="text-sm text-gray-700">重新配网</span>
            </div>
          </motion.button>
        </Card>

        {/* Unbind */}
        <Card className="p-4">
          <motion.button
            whileTap={{ scale: 0.98 }}
            onClick={() => setShowUnbindDialog(true)}
            className="w-full flex items-center justify-center gap-2 py-2 text-danger font-medium"
          >
            <Trash2 size={18} />
            解绑设备
          </motion.button>
        </Card>
      </div>

      {/* Volume Drawer */}
      <Drawer
        isOpen={showVolumeDrawer}
        onClose={() => setShowVolumeDrawer(false)}
        title="音量调节"
        height="h-1/3"
      >
        <div className="space-y-4">
          <div>
            <label className="block text-sm text-gray-600 mb-2">
              音量大小
            </label>
            <input
              type="range"
              min="0"
              max="100"
              value={volume}
              onChange={(e) => setVolume(parseInt(e.target.value))}
              className="w-full"
            />
            <div className="flex justify-between text-xs text-gray-400 mt-1">
              <span>0</span>
              <span>{volume}</span>
              <span>100</span>
            </div>
          </div>
          <motion.button
            whileTap={{ scale: 0.98 }}
            onClick={() => setShowVolumeDrawer(false)}
            className="w-full py-2 bg-primary text-white rounded-xl text-sm font-medium"
          >
            保存
          </motion.button>
        </div>
      </Drawer>

      {/* Call Dialog */}
      {showCallDialog && (
        <CallDialog
          device={device}
          onClose={() => setShowCallDialog(false)}
        />
      )}

      {/* Re-network Confirm Dialog */}
      <AnimatePresence>
        {showReNetworkDialog && (
          <ConfirmDialog
            message="确认为该设备重新配网？"
            onConfirm={handleReNetworkConfirm}
            onCancel={() => setShowReNetworkDialog(false)}
          />
        )}
      </AnimatePresence>

      {/* Unbind Confirm Dialog */}
      <AnimatePresence>
        {showUnbindDialog && (
          <ConfirmDialog
            message="确定从该家庭中解绑该设备？"
            onConfirm={handleUnbindConfirm}
            onCancel={() => setShowUnbindDialog(false)}
          />
        )}
      </AnimatePresence>
    </div>
  )
}

/* ===== 通用确认弹窗组件 ===== */
const ConfirmDialog = ({ message, onConfirm, onCancel }) => {
  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="fixed inset-0 bg-black/60 flex items-center justify-center z-50"
    >
      <motion.div
        initial={{ scale: 0.8, opacity: 0 }}
        animate={{ scale: 1, opacity: 1 }}
        exit={{ scale: 0.8, opacity: 0 }}
        transition={{ type: 'spring', duration: 0.3 }}
        className="bg-white rounded-2xl p-6 mx-4 w-full max-w-sm"
      >
        <div className="text-center">
          <p className="text-base text-gray-800 mb-6">{message}</p>
          <div className="flex gap-3">
            <motion.button
              whileTap={{ scale: 0.95 }}
              onClick={onCancel}
              className="flex-1 py-3 bg-gray-100 rounded-xl text-gray-700 font-medium text-sm"
            >
              取消
            </motion.button>
            <motion.button
              whileTap={{ scale: 0.95 }}
              onClick={onConfirm}
              className="flex-1 py-3 bg-primary rounded-xl text-white font-medium text-sm"
            >
              确定
            </motion.button>
          </div>
        </div>
      </motion.div>
    </motion.div>
  )
}

/* ===== 双向对讲弹窗 ===== */
const CallDialog = ({ device, onClose }) => {
  return (
    <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50">
      <motion.div
        initial={{ scale: 0.8, opacity: 0 }}
        animate={{ scale: 1, opacity: 1 }}
        exit={{ scale: 0.8, opacity: 0 }}
        className="bg-white rounded-3xl p-6 mx-4 w-full max-w-sm"
      >
        <div className="text-center">
          <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
            <Mic size={32} className="text-primary" />
          </div>
          <h3 className="text-lg font-semibold text-gray-800 mb-1">
            正在对讲
          </h3>
          <p className="text-sm text-gray-500 mb-4">
            {device?.name || '设备'} · {device?.location || ''}
          </p>

          <div className="flex justify-center gap-6 mb-6">
            <motion.button
              whileTap={{ scale: 0.9 }}
              className="w-14 h-14 bg-gray-100 rounded-full flex items-center justify-center"
            >
              <Mic size={24} className="text-gray-600" />
            </motion.button>
            <motion.button
              whileTap={{ scale: 0.9 }}
              className="w-16 h-16 bg-primary rounded-full flex items-center justify-center"
            >
              <Phone size={20} className="text-white" />
            </motion.button>
            <motion.button
              whileTap={{ scale: 0.9 }}
              className="w-14 h-14 bg-gray-100 rounded-full flex items-center justify-center"
            >
              <Volume2 size={24} className="text-gray-600" />
            </motion.button>
          </div>

          <motion.button
            whileTap={{ scale: 0.95 }}
            onClick={onClose}
            className="w-full py-3 text-danger font-medium"
          >
            挂断
          </motion.button>
        </div>
      </motion.div>
    </div>
  )
}

export default DeviceManagement