import { motion } from 'framer-motion'
import { MousePointerClick, Smartphone, AlertTriangle } from 'lucide-react'
import Card from '../common/Card'
import { mockEventStats } from '../../utils/mockData'

const statIcons = {
  pat: MousePointerClick,
  button: Smartphone,
  fall: AlertTriangle,
}

const statColors = {
  pat: 'text-orange-500',
  button: 'text-green-500',
  fall: 'text-danger',
}

const EventStatsTab = () => {
  return (
    <div className="p-4 space-y-4">
      <Card className="p-4">
        <div className="space-y-3">
          {mockEventStats.map((event, index) => {
            const Icon = statIcons[event.type] || AlertTriangle
            const iconColor = statColors[event.type] || 'text-gray-500'

            return (
              <motion.div
                key={event.id}
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: index * 0.1 }}
                className="border-b border-gray-100 pb-3 last:border-0 last:pb-0"
              >
                <div className="flex items-center gap-3">
                  <div className="w-8 h-8 rounded-full bg-gray-50 flex items-center justify-center flex-shrink-0">
                    <Icon size={18} className={iconColor} />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center justify-between">
                      <p className="font-medium text-gray-800">{event.title}</p>
                      <span className="text-xs text-gray-500 flex-shrink-0 ml-2">{event.time}</span>
                    </div>
                    <p className="text-sm text-gray-500 mt-1">
                      {event.location}
                    </p>
                  </div>
                </div>
              </motion.div>
            )
          })}
        </div>
      </Card>
    </div>
  )
}

export default EventStatsTab