import { useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import BottomNav from './components/BottomNav'
import Home from './pages/Home'
import Stats from './pages/Stats'
import Function from './pages/Function'
import Profile from './pages/Profile'
import DeviceManagement from './pages/DeviceManagement'
import MedicationReminder from './pages/MedicationReminder'
import DialectRescueGuide from './pages/DialectRescueGuide'
import IntercomDialog from './pages/IntercomDialog'
import FamilyInfoPage from './pages/FamilyInfoPage'
import FamilyMembersPage from './pages/FamilyMembersPage'

const pageVariants = {
  initial: { opacity: 0, y: 10 },
  animate: { opacity: 1, y: 0 },
  exit: { opacity: 0, y: -10 },
}

const pageTransition = {
  duration: 0.25,
  ease: 'easeInOut',
}

const App = () => {
  const [activeTab, setActiveTab] = useState('home')
  const [currentView, setCurrentView] = useState('main')
  const [selectedDevice, setSelectedDevice] = useState(null)
  const [functionSubView, setFunctionSubView] = useState(null)
  const [profileSubView, setProfileSubView] = useState(null)

  const handleDeviceClick = (device) => {
    setSelectedDevice(device)
    setCurrentView('device-management')
  }

  const handleBack = () => {
    setCurrentView('main')
    setSelectedDevice(null)
    setFunctionSubView(null)
    setProfileSubView(null)
  }

  const handleFunctionNavigate = (subView) => {
    setFunctionSubView(subView)
    setCurrentView('function-sub')
  }

  const handleFunctionBack = () => {
    setCurrentView('main')
    setFunctionSubView(null)
  }

  const handleProfileNavigate = (subView) => {
    setProfileSubView(subView)
    setCurrentView('profile-sub')
  }

  const handleProfileBack = () => {
    setCurrentView('main')
    setProfileSubView(null)
  }

  const renderPage = () => {
    if (currentView === 'device-management') {
      return <DeviceManagement device={selectedDevice} onBack={handleBack} />
    }

    if (currentView === 'function-sub') {
      switch (functionSubView) {
        case 'medication':
          return <MedicationReminder onBack={handleFunctionBack} />
        case 'dialect':
          return <DialectRescueGuide onBack={handleFunctionBack} />
        default:
          return <Function onNavigate={handleFunctionNavigate} />
      }
    }

    if (currentView === 'profile-sub') {
      switch (profileSubView) {
        case 'family-info':
          return <FamilyInfoPage onBack={handleProfileBack} onSave={handleProfileBack} />
        case 'family-members':
          return <FamilyMembersPage onBack={handleProfileBack} />
        default:
          return <Profile onNavigate={handleProfileNavigate} />
      }
    }

    switch (activeTab) {
      case 'home':
        return <Home onDeviceClick={handleDeviceClick} />
      case 'stats':
        return <Stats />
      case 'function':
        return <Function onNavigate={handleFunctionNavigate} />
      case 'profile':
        return <Profile onNavigate={handleProfileNavigate} />
      default:
        return <Home onDeviceClick={handleDeviceClick} />
    }
  }

  const showBottomNav = currentView === 'main'

  const pageKey = currentView === 'device-management'
    ? 'device-management'
    : currentView === 'function-sub'
    ? `function-${functionSubView}`
    : currentView === 'profile-sub'
    ? `profile-${profileSubView}`
    : activeTab

  return (
    <div className="min-h-screen bg-bg pb-16 font-['PingFangSC','Helvetica','Arial',sans-serif]">
      <AnimatePresence mode="wait">
        <motion.div
          key={pageKey}
          initial="initial"
          animate="animate"
          exit="exit"
          variants={pageVariants}
          transition={pageTransition}
          className="pb-16"
        >
          {renderPage()}
        </motion.div>
      </AnimatePresence>
      {showBottomNav && (
        <BottomNav activeTab={activeTab} setActiveTab={setActiveTab} />
      )}
    </div>
  )
}

export default App