import { useState } from 'react'
import { motion } from 'framer-motion'
import { ArrowLeft, ChevronDown, X } from 'lucide-react'
import Card from '../components/common/Card'

const FamilyInfoPage = ({ onBack, onSave }) => {
  const [familyName, setFamilyName] = useState('爷爷奶奶家')
  const [showElderInfo, setShowElderInfo] = useState(true)
  const [elders, setElders] = useState([
    { id: 1, name: '刘强', gender: 'male', age: 80 },
  ])
  const [contacts, setContacts] = useState([
    { id: 1, name: '王铁柱', phone: '13097435306' },
    { id: 2, name: '王铁柱', phone: '13097435306' },
    { id: 3, name: '', phone: '' },
  ])

  const handleAddElder = () => {
    setElders([...elders, { id: Date.now(), name: '', gender: 'male', age: '' }])
  }

  const handleRemoveElder = (id) => {
    setElders(elders.filter(e => e.id !== id))
  }

  const handleContactChange = (id, field, value) => {
    setContacts(contacts.map(c => 
      c.id === id ? { ...c, [field]: value } : c
    ))
  }

  return (
    <div className="min-h-screen bg-gray-50 pt-12 pb-16">
      {/* Header */}
      <div className="px-4 pt-4 pb-4 flex items-center justify-between relative bg-white">
        <motion.button
          whileTap={{ scale: 0.9 }}
          onClick={onBack}
          className="text-gray-600"
        >
          <ArrowLeft size={24} />
        </motion.button>
        <h1 className="text-lg font-semibold text-gray-800">家庭资料</h1>
        <motion.button
          whileTap={{ scale: 0.9 }}
          onClick={onSave}
          className="text-sm font-medium"
          style={{ color: '#007AFF' }}
        >
          保存
        </motion.button>
      </div>

      <div className="px-4 py-6 space-y-4">
        {/* Family Name */}
        <Card className="p-4">
          <input
            type="text"
            value={familyName}
            onChange={(e) => setFamilyName(e.target.value)}
            placeholder="请输入家庭名称"
            className="w-full text-base text-gray-800 outline-none"
          />
        </Card>

        {/* Elder Info Section */}
        <Card className="p-4">
          <motion.button
            whileTap={{ scale: 0.98 }}
            onClick={() => setShowElderInfo(!showElderInfo)}
            className="w-full flex items-center justify-between mb-4"
          >
            <span className="text-sm font-medium text-gray-700">老人资料</span>
            <motion.div
              animate={{ rotate: showElderInfo ? 180 : 0 }}
              transition={{ duration: 0.2 }}
            >
              <ChevronDown size={18} className="text-gray-400" />
            </motion.div>
          </motion.button>

          <AnimatePresence>
            {showElderInfo && (
              <motion.div
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: 'auto' }}
                exit={{ opacity: 0, height: 0 }}
                className="space-y-4"
              >
                {elders.map((elder, index) => (
                  <div key={elder.id} className="space-y-3">
                    {index > 0 && (
                      <div className="flex justify-end">
                        <motion.button
                          whileTap={{ scale: 0.9 }}
                          onClick={() => handleRemoveElder(elder.id)}
                          className="text-xs text-red-500"
                        >
                          删除
                        </motion.button>
                      </div>
                    )}
                    {/* Name */}
                    <div>
                      <label className="block text-sm text-gray-700 mb-1.5">
                        <span className="text-red-500">*</span> 姓名
                      </label>
                      <input
                        type="text"
                        value={elder.name}
                        onChange={(e) => {
                          const newElders = [...elders]
                          newElders[index].name = e.target.value
                          setElders(newElders)
                        }}
                        placeholder="请输入姓名"
                        className="w-full px-3 py-2.5 bg-gray-50 rounded-xl border border-gray-100 text-sm outline-none focus:border-primary"
                      />
                    </div>

                    {/* Gender */}
                    <div>
                      <label className="block text-sm text-gray-700 mb-1.5">
                        <span className="text-red-500">*</span> 性别
                      </label>
                      <div className="flex gap-2">
                        {['male', 'female'].map(gender => (
                          <motion.button
                            key={gender}
                            whileTap={{ scale: 0.95 }}
                            onClick={() => {
                              const newElders = [...elders]
                              newElders[index].gender = gender
                              setElders(newElders)
                            }}
                            className={`flex-1 py-2 rounded-xl text-sm font-medium border ${
                              elder.gender === gender
                                ? 'border-orange-400 text-orange-500 bg-orange-50'
                                : 'border-gray-200 text-gray-700 bg-white'
                            }`}
                          >
                            {gender === 'male' ? '男' : '女'}
                          </motion.button>
                        ))}
                      </div>
                    </div>

                    {/* Age */}
                    <div>
                      <label className="block text-sm text-gray-700 mb-1.5">
                        <span className="text-red-500">*</span> 年龄
                      </label>
                      <input
                        type="number"
                        value={elder.age}
                        onChange={(e) => {
                          const newElders = [...elders]
                          newElders[index].age = e.target.value
                          setElders(newElders)
                        }}
                        placeholder="请输入年龄"
                        className="w-full px-3 py-2.5 bg-gray-50 rounded-xl border border-gray-100 text-sm outline-none focus:border-primary"
                      />
                    </div>
                  </div>
                ))}

                {/* Add Another Elder Button */}
                <motion.button
                  whileTap={{ scale: 0.98 }}
                  onClick={handleAddElder}
                  className="w-full py-3 rounded-xl border-2 border-dashed border-gray-300 text-sm text-gray-600 font-medium"
                >
                  + 添加另一位老人
                </motion.button>
              </motion.div>
            )}
          </AnimatePresence>
        </Card>

        {/* Emergency Contacts */}
        {contacts.map((contact, index) => (
          <Card key={contact.id} className="p-4">
            <h3 className="text-sm font-medium text-gray-700 text-center mb-3">
              紧急联系人{index + 1}
            </h3>
            <div className="space-y-3">
              <div>
                <label className="block text-sm text-gray-700 mb-1.5">
                  {contact.name || contact.phone ? <span className="text-red-500">*</span> : ''} 姓名
                </label>
                <input
                  type="text"
                  value={contact.name}
                  onChange={(e) => handleContactChange(contact.id, 'name', e.target.value)}
                  placeholder={contact.name || contact.phone ? '' : '请输入联系人姓名'}
                  className="w-full px-3 py-2.5 bg-gray-50 rounded-xl border border-gray-100 text-sm outline-none focus:border-primary"
                />
              </div>
              <div>
                <label className="block text-sm text-gray-700 mb-1.5">
                  {contact.name || contact.phone ? <span className="text-red-500">*</span> : ''} 电话
                </label>
                <input
                  type="tel"
                  value={contact.phone}
                  onChange={(e) => handleContactChange(contact.id, 'phone', e.target.value)}
                  placeholder={contact.name || contact.phone ? '' : '请输入联系人电话'}
                  className="w-full px-3 py-2.5 bg-gray-50 rounded-xl border border-gray-100 text-sm outline-none focus:border-primary"
                />
              </div>
            </div>
          </Card>
        ))}

        {/* Dissolve Family Button */}
        <motion.button
          whileTap={{ scale: 0.98 }}
          className="w-full py-3.5 rounded-2xl text-white font-medium"
          style={{ backgroundColor: '#FFD6B3' }}
        >
          解散家庭
        </motion.button>
      </div>
    </div>
  )
}

// Simple AnimatePresence replacement for this usage
const AnimatePresence = ({ children }) => {
  return <>{children}</>
}

export default FamilyInfoPage