import { useState } from 'react'
import { motion } from 'framer-motion'
import {
  Volume2,
  MousePointerClick,
  Wifi,
  Settings,
  ChevronRight,
  Bell,
  BellOff,
  Phone,
  AlertTriangle,
  Activity,
  Wind,
} from 'lucide-react'
import FamilySelector from '../components/FamilySelector'
import Card from '../components/common/Card'
import Carousel from '../components/Carousel'
import { mockDailyEvents, mockDevices, mockFamily } from '../utils/mockData'

const Home = ({ onDeviceClick }) => {
  const [currentFamily, setCurrentFamily] = useState(mockFamily)

  // Carousel items with images
  const carouselItems = [
    {
      content: (
        <img
          src="/yaolao/images/banner1.jpg"
          alt="一键紧急呼救"
          className="w-full h-full object-cover"
        />
      ),
    },
    {
      content: (
        <img
          src="/yaolao/images/banner2.jpg"
          alt="无感睡眠监测"
          className="w-full h-full object-cover"
        />
      ),
    },
    {
      content: (
        <img
          src="/yaolao/images/banner3.jpg"
          alt="AI跌倒监测"
          className="w-full h-full object-cover"
        />
      ),
    },
  ]

  // Updated daily overview items with custom icons
  const dailyItems = [
    {
      label: '呼救',
      value: `${mockDailyEvents.rescue} 次`,
      icon: '/yaolao/images/icon-sos.png',
      color: 'text-blue-500',
    },
    {
      label: '跌倒',
      value: mockDailyEvents.fall ? '有' : '无',
      icon: '/yaolao/images/icon-fall.png',
      color: mockDailyEvents.fall ? 'text-danger' : 'text-gray-400',
    },
    {
      label: '生命体征',
      value: mockDailyEvents.vitalSigns === 'normal' ? '正常' : '异常',
      icon: 'activity', // keep original icon indicator
      color: mockDailyEvents.vitalSigns === 'normal' ? 'text-green-500' : 'text-danger',
    },
    {
      label: '咳嗽',
      value: mockDailyEvents.cough === 'normal' ? '正常' : '异常',
      icon: '/yaolao/images/icon-cough.png',
      color: mockDailyEvents.cough === 'normal' ? 'text-green-500' : 'text-danger',
    },
  ]

  const getDeviceIcon = (type) => {
    switch (type) {
      case 'sensor':
        return <img src="/yaolao/images/icon-caller.png" alt="智能呼叫器" className="w-5 h-5" />
      case 'radar':
        return <img src="/yaolao/images/icon-radar.png" alt="跌倒监测器" className="w-5 h-5" />
      case 'bed':
        return <img src="/yaolao/images/icon-bed.png" alt="智能监护垫" className="w-5 h-5" />
      default:
        return <Settings size={20} />
    }
  }

  return (
    <div className="min-h-screen bg-bg pb-16">
      {/* Header with family selector and bell */}
      <div className="px-4 pt-8 pb-4 flex items-center justify-between">
        <FamilySelector
          currentFamily={currentFamily}
          onFamilyChange={setCurrentFamily}
        />
        <motion.button
          whileTap={{ scale: 0.9 }}
          className="w-10 h-10 bg-white rounded-full flex items-center justify-center shadow-card"
        >
          <Bell size={20} className="text-gray-600" />
        </motion.button>
      </div>

      {/* Companion text */}
      <div className="px-4 mb-4">
        <p className="text-sm text-gray-500">万岁鲸陪伴您的第100天</p>
      </div>

      {/* Carousel */}
      <div className="px-4 mb-4">
        <Carousel items={carouselItems} autoPlay interval={5000} height="h-36" />
      </div>

      {/* Daily Overview - title outside the card */}
      <div className="px-4 mb-2">
        <h3 className="text-sm font-medium text-gray-500">每日概况</h3>
      </div>
      <div className="px-4 mb-4">
        <Card className="p-4">
          <div className="grid grid-cols-4 gap-2 text-center">
            {dailyItems.map((item, index) => {
              return (
                <motion.div
                  key={item.label}
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: index * 0.1 }}
                  className="flex flex-col items-center"
                >
                  <div className={`w-10 h-10 rounded-full bg-gray-50 flex items-center justify-center mb-1`}>
                    {item.icon === 'activity' ? (
                      <Activity size={20} className={item.color} />
                    ) : (
                      <img src={item.icon} alt={item.label} className="w-6 h-6" />
                    )}
                  </div>
                  <p className="text-xs text-gray-500 mb-0.5">{item.label}</p>
                  <p className={`text-sm font-semibold ${item.color}`}>
                    {item.value}
                  </p>
                </motion.div>
              )
            })}
          </div>
        </Card>
      </div>

      {/* Device List - title aligned with daily overview */}
      <div className="px-4 mb-2">
        <h3 className="text-sm font-medium text-gray-500">家庭设备</h3>
      </div>
      <div className="px-4 mb-4">
        <div className="space-y-3">
          {mockDevices.map((device, index) => (
            <motion.div
              key={device.id}
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: index * 0.1 }}
            >
              <Card
                className="p-3 flex items-center justify-between"
                hover
                onClick={() => onDeviceClick && onDeviceClick(device)}
              >
                <div className="flex items-center gap-3">
                  <div className={`w-10 h-10 rounded-full flex items-center justify-center ${
                    device.status === 'online' ? 'bg-green-50' : 'bg-gray-50'
                  }`}>
                    {getDeviceIcon(device.type)}
                  </div>
                  <div>
                    <p className="font-medium text-gray-800">{device.name}</p>
                    <p className="text-sm text-gray-500">{device.location}</p>
                  </div>
                </div>

                <div className="flex items-center gap-2">
                  <span className={`text-xs px-2 py-0.5 rounded-full ${
                    device.status === 'online'
                      ? 'bg-green-100 text-green-600'
                      : 'bg-gray-100 text-gray-500'
                  }`}>
                    {device.status === 'online' ? '在线' : '离线'}
                  </span>
                  <ChevronRight size={16} className="text-gray-400" />
                </div>
              </Card>
            </motion.div>
          ))}
        </div>
      </div>
    </div>
  )
}

export default Home
