import { useState } from 'react'
import { motion } from 'framer-motion'
import {
  User,
  Edit3,
  ChevronRight,
  Users,
  FileText,
  Shield,
  Info,
  Phone,
  LogOut,
} from 'lucide-react'
import Card from '../components/common/Card'
import Drawer from '../components/common/Drawer'
import { mockFamily, mockFamilies } from '../utils/mockData'

const Profile = ({ onNavigate }) => {
  const [family, setFamily] = useState(mockFamily)
  const [nickname, setNickname] = useState('微信用户')
  const [showMemberDrawer, setShowMemberDrawer] = useState(false)
  const [isEditingNickname, setIsEditingNickname] = useState(false)

  const menuItems = [
    {
      id: 'family',
      label: '家庭资料',
      desc: '家庭信息管理',
      icon: Users,
      onClick: () => onNavigate?.('family-info'),
    },
    {
      id: 'members',
      label: '家庭成员',
      desc: '成员列表管理',
      icon: Users,
      onClick: () => onNavigate?.('family-members'),
    },
    {
      id: 'protocol',
      label: '用户协议',
      desc: '查看用户协议',
      icon: FileText,
      onClick: () => {},
    },
    {
      id: 'privacy',
      label: '隐私政策',
      desc: '查看隐私政策',
      icon: Shield,
      onClick: () => {},
    },
    {
      id: 'about',
      label: '关于我们',
      desc: '了解我们',
      icon: Info,
      onClick: () => {},
    },
    {
      id: 'contact',
      label: '联系我们',
      desc: '联系客服',
      icon: Phone,
      onClick: () => {},
    },
  ]

  const familyMembers = [
    {
      id: 'elder-001',
      name: family.members[0]?.name || '林老爷',
      age: family.members[0]?.age || 78,
      phone: family.members[0]?.phone || '138****0001',
      avatar: '👴',
      role: 'elder',
      isElder: true,
    },
    {
      id: 'caregiver-001',
      name: '林女士',
      phone: '138****0002',
      avatar: '👩',
      role: 'caregiver',
      isElder: false,
    },
  ]

  return (
    <div className="min-h-screen bg-bg pt-12 pb-16">
      <div className="px-4 py-6">
        {/* Avatar & Nickname */}
        <div className="flex flex-col items-center mb-6">
          <div className="w-20 h-20 rounded-full flex items-center justify-center" style={{ backgroundColor: '#007AFF' }}>
            <User size={40} className="text-white" />
          </div>
          <div className="flex items-center gap-2 mt-3">
            {isEditingNickname ? (
              <input
                type="text"
                value={nickname}
                onChange={(e) => setNickname(e.target.value)}
                onBlur={() => setIsEditingNickname(false)}
                onKeyDown={(e) => e.key === 'Enter' && setIsEditingNickname(false)}
                autoFocus
                className="text-xl font-semibold text-gray-800 text-center border-b-2 border-primary outline-none"
              />
            ) : (
              <>
                <h1 className="text-xl font-semibold text-gray-800">{nickname}</h1>
                <motion.button
                  whileTap={{ scale: 0.9 }}
                  onClick={() => setIsEditingNickname(true)}
                  className="text-gray-500"
                >
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" className="w-4 h-4">
                    <path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7" />
                    <path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z" />
                  </svg>
                </motion.button>
              </>
            )}
          </div>
        </div>

        {/* Menu Items */}
        <div className="space-y-3">
          {menuItems.map((item, index) => {
            const Icon = item.icon
            return (
              <motion.div
                key={item.id}
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: index * 0.05 }}
              >
                <Card className="p-0 overflow-hidden">
                  <motion.button
                    whileTap={{ scale: 0.98 }}
                    onClick={item.onClick}
                    className="w-full flex items-center gap-3 py-2.5 px-4 text-left"
                  >
                    <div className="flex items-center gap-3 flex-1">
                      <div className="w-10 h-10 rounded-xl flex items-center justify-center" style={{ backgroundColor: '#F5F5F5' }}>
                        <Icon size={20} className="text-gray-600" />
                      </div>
                      <div>
                        <p className="text-sm font-medium text-gray-800">{item.label}</p>
                      </div>
                    </div>
                    <ChevronRight size={18} className="text-gray-400" />
                  </motion.button>
                </Card>
              </motion.div>
            )
          })}
        </div>

        {/* Logout */}
        <motion.button
          whileTap={{ scale: 0.98 }}
          className="w-full flex items-center justify-center gap-2 py-2.5 px-4 mt-6 bg-gray-100 rounded-2xl text-gray-700 font-medium"
        >
          <LogOut size={18} />
          退出登录
        </motion.button>
      </div>

      {/* Member Management Drawer */}
      <Drawer
        isOpen={showMemberDrawer}
        onClose={() => setShowMemberDrawer(false)}
        title="家庭资料与成员"
        height="h-3/4"
      >
        <div className="space-y-6">
          {/* Family Info */}
          <div>
            <h4 className="text-sm font-medium text-gray-700 mb-3">家庭信息</h4>
            <Card className="p-4">
              <div className="space-y-3 text-sm">
                <div className="flex justify-between">
                  <span className="text-gray-500">名称</span>
                  <span className="text-gray-800">{family.name}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-gray-500">地址</span>
                  <span className="text-gray-800">{family.address}</span>
                </div>
              </div>
            </Card>
          </div>

          {/* Members */}
          <div>
            <h4 className="text-sm font-medium text-gray-700 mb-3">成员列表</h4>
            <div className="space-y-3">
              {familyMembers.map((member) => (
                <Card key={member.id} className="p-4">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 bg-gray-100 rounded-full flex items-center justify-center text-xl">
                        {member.avatar}
                      </div>
                      <div>
                        <p className="font-medium text-gray-800">{member.name}</p>
                        {member.isElder && (
                          <p className="text-xs text-gray-500">
                            {member.age}岁 · {member.phone}
                          </p>
                        )}
                        {!member.isElder && (
                          <p className="text-xs text-gray-500">{member.phone}</p>
                        )}
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      {member.isElder && (
                        <span className="text-xs px-2 py-0.5 bg-orange-50 text-orange-500 rounded-full">
                          老人
                        </span>
                      )}
                      {!member.isElder && (
                        <span className="text-xs px-2 py-0.5 bg-blue-50 text-primary rounded-full">
                          管理员
                        </span>
                      )}
                      <ChevronRight size={16} className="text-gray-400" />
                    </div>
                  </div>
                </Card>
              ))}
            </div>
          </div>
        </div>
      </Drawer>
    </div>
  )
}

export default Profile