import { useState, useEffect, useRef, useCallback } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { Settings } from 'lucide-react'
import Card from '../common/Card'

// ==================== SVG 图标（内联） ====================
const ICONS = {
  fall: (
    <svg viewBox="0 0 120 120" fill="none" className="w-full h-full">
      <circle cx="72" cy="22" r="10" fill="#FF3B30" />
      <path d="M30 98l18-36 14 10 24-42" stroke="#FF3B30" strokeWidth="5" strokeLinecap="round" strokeLinejoin="round" />
      <path d="M22 98h76" stroke="#FF3B30" strokeWidth="3" strokeLinecap="round" opacity="0.4" />
      <text x="60" y="112" textAnchor="middle" fill="#FF3B30" fontSize="11" fontWeight="600" opacity="0.6">!</text>
    </svg>
  ),
  stay: (
    <svg viewBox="0 0 120 120" fill="none" className="w-full h-full">
      <circle cx="60" cy="60" r="38" stroke="#FF9500" strokeWidth="3" opacity="0.3" />
      <circle cx="60" cy="60" r="38" stroke="#FF9500" strokeWidth="3" strokeDasharray="180 60" strokeLinecap="round" transform="rotate(-90 60 60)" />
      <circle cx="60" cy="28" r="8" fill="#FF9500" />
      <path d="M44 88c0-8.837 7.163-16 16-16s16 7.163 16 16" stroke="#FF9500" strokeWidth="4" strokeLinecap="round" />
      <path d="M60 44v20l14 9" stroke="#FF9500" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  ),
  present: (
    <svg viewBox="0 0 120 120" fill="none" className="w-full h-full">
      <circle cx="60" cy="32" r="14" fill="#34C759" />
      <path d="M28 98c0-17.673 14.327-32 32-32s32 14.327 32 32" stroke="#34C759" strokeWidth="5" strokeLinecap="round" />
      <circle cx="88" cy="88" r="16" fill="#34C759" opacity="0.15" />
      <path d="M88 82v12M82 88h12" stroke="#34C759" strokeWidth="2.5" strokeLinecap="round" />
    </svg>
  ),
  absent: (
    <svg viewBox="0 0 120 120" fill="none" className="w-full h-full">
      <rect x="20" y="30" width="80" height="60" rx="8" stroke="#AEAEB2" strokeWidth="3" fill="#F5F6F8" />
      <path d="M40 60h40M40 72h28" stroke="#AEAEB2" strokeWidth="2.5" strokeLinecap="round" />
      <circle cx="60" cy="48" r="6" stroke="#AEAEB2" strokeWidth="2" fill="none" opacity="0.5" />
    </svg>
  ),
  loading: (
    <svg viewBox="0 0 120 120" fill="none" className="w-full h-full">
      <circle cx="60" cy="60" r="36" stroke="#E8E8ED" strokeWidth="4" />
      <circle cx="60" cy="60" r="36" stroke="#007AFF" strokeWidth="4" strokeLinecap="round" strokeDasharray="80 150">
        <animateTransform attributeName="transform" type="rotate" from="0 60 60" to="360 60 60" dur="1.2s" repeatCount="indefinite" />
      </circle>
    </svg>
  ),
}

// ==================== 常量 ====================
const ALERT_DISPLAY_MS = 5 * 60 * 1000 // 5分钟
const ALERT_HISTORY_MAX = 5

const STORAGE_KEY = 'wansuijing_radar_settings'
const HISTORY_KEY = 'wansuijing_alert_history'

const DEFAULT_SETTINGS = { fallDelay: 30, stayDuration: 5 }

// ==================== 工具函数 ====================
const pad = (n) => (n < 10 ? '0' + n : '' + n)

const formatTime = (ts) => {
  const d = new Date(ts)
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}`
}

const formatClock = (ts) => {
  const d = new Date(ts)
  return `${pad(d.getHours())}:${pad(d.getMinutes())}`
}

const formatDuration = (ms) => {
  const totalMin = Math.max(1, Math.floor(ms / 60000))
  const hours = Math.floor(totalMin / 60)
  const minutes = totalMin % 60
  if (hours > 0 && minutes > 0) return `${hours}小时${minutes}分钟`
  if (hours > 0) return `${hours}小时`
  return `${minutes}分钟`
}

const loadSettings = () => {
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    if (raw) return { ...DEFAULT_SETTINGS, ...JSON.parse(raw) }
  } catch (e) { /* ignore */ }
  return { ...DEFAULT_SETTINGS }
}

const loadHistory = () => {
  try {
    const raw = localStorage.getItem(HISTORY_KEY)
    if (raw) return JSON.parse(raw).slice(0, ALERT_HISTORY_MAX)
  } catch (e) { /* ignore */ }
  return []
}

// ==================== 组件 ====================
const FallDetectionTab = () => {
  const [settings, setSettings] = useState(loadSettings)
  const [alertHistory, setAlertHistory] = useState(loadHistory)
  const [connected, setConnected] = useState(false)
  const [presence, setPresence] = useState(false)
  const [fallDetected, setFallDetected] = useState(false)
  const [fallConfirmed, setFallConfirmed] = useState(false)
  const [fallSince, setFallSince] = useState(null)
  const [presenceSince, setPresenceSince] = useState(null)
  const [fallAlertActive, setFallAlertActive] = useState(false)
  const [fallAlertUntil, setFallAlertUntil] = useState(null)
  const [stayAlertActive, setStayAlertActive] = useState(false)
  const [stayAlertUntil, setStayAlertUntil] = useState(null)
  const [stayDetected, setStayDetected] = useState(false)
  const [showSettings, setShowSettings] = useState(false)

  const simStepRef = useRef(0)
  const fallDelayTimerRef = useRef(null)
  const stayTimerRef = useRef(null)

  // ── 连接模拟 ──
  useEffect(() => {
    const timer = setTimeout(() => {
      setConnected(true)
      setPresence(true)
      setPresenceSince(Date.now())
    }, 1500)
    return () => clearTimeout(timer)
  }, [])

  // ── 模拟雷达数据变化 ──
  useEffect(() => {
    if (!connected) return

    const interval = setInterval(() => {
      // 告警期间不切换
      if (fallAlertActive || stayAlertActive) return

      simStepRef.current++
      const mod = simStepRef.current % 8

      if (mod === 0) {
        // 模拟跌倒
        setPresence(true)
        setFallDetected(true)
        setFallSince(Date.now())
        setPresenceSince(prev => prev || Date.now())
      } else if (mod === 3) {
        // 模拟长时间驻留（提前触发）
        const fakeSince = Date.now() - (settings.stayDuration * 60 * 1000 + 2000)
        setPresence(true)
        setPresenceSince(fakeSince)
      } else if (mod === 5) {
        // 模拟无人
        setPresence(false)
        setPresenceSince(null)
        setFallDetected(false)
        setFallSince(null)
        setStayDetected(false)
      } else {
        // 有人正常
        if (!presence) {
          setPresence(true)
          setPresenceSince(Date.now())
        }
      }
    }, 12000)

    return () => clearInterval(interval)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [connected, fallAlertActive, stayAlertActive])

  // ── 跌倒延迟确认 ──
  useEffect(() => {
    if (fallDetected && !fallConfirmed && fallSince) {
      const delay = settings.fallDelay * 1000
      fallDelayTimerRef.current = setTimeout(() => {
        setFallConfirmed(true)
        setFallAlertActive(true)
        const until = Date.now() + ALERT_DISPLAY_MS
        setFallAlertUntil(until)
        addAlertRecord('fall')
      }, delay)
    }
    return () => {
      if (fallDelayTimerRef.current) {
        clearTimeout(fallDelayTimerRef.current)
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [fallDetected, fallConfirmed, fallSince, settings.fallDelay])

  // ── 长时间驻留检测 ──
  useEffect(() => {
    if (presence && presenceSince && !stayAlertActive) {
      const stayMs = settings.stayDuration * 60 * 1000
      const elapsed = Date.now() - presenceSince
      const remaining = Math.max(0, stayMs - elapsed)

      stayTimerRef.current = setTimeout(() => {
        setStayDetected(true)
        setStayAlertActive(true)
        const until = Date.now() + ALERT_DISPLAY_MS
        setStayAlertUntil(until)
        addAlertRecord('stay')
      }, remaining)
    }
    return () => {
      if (stayTimerRef.current) {
        clearTimeout(stayTimerRef.current)
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [presence, presenceSince, stayAlertActive, settings.stayDuration])

  // ── 告警 5 分钟后恢复 ──
  useEffect(() => {
    if (!fallAlertActive || !fallAlertUntil) return
    const remaining = Math.max(0, fallAlertUntil - Date.now())
    const timer = setTimeout(() => {
      setFallAlertActive(false)
      setFallAlertUntil(null)
      setFallDetected(false)
      setFallConfirmed(false)
      setFallSince(null)
    }, remaining)
    return () => clearTimeout(timer)
  }, [fallAlertActive, fallAlertUntil])

  useEffect(() => {
    if (!stayAlertActive || !stayAlertUntil) return
    const remaining = Math.max(0, stayAlertUntil - Date.now())
    const timer = setTimeout(() => {
      setStayAlertActive(false)
      setStayAlertUntil(null)
      setStayDetected(false)
      if (presence) {
        setPresenceSince(Date.now())
      }
    }, remaining)
    return () => clearTimeout(timer)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [stayAlertActive, stayAlertUntil])

  // ── 添加告警记录 ──
  const addAlertRecord = useCallback((type) => {
    const label = type === 'fall' ? '跌倒告警' : '长时间驻留告警'
    setAlertHistory(prev => {
      const next = [{ time: formatTime(Date.now()), event: label, type }, ...prev].slice(0, ALERT_HISTORY_MAX)
      localStorage.setItem(HISTORY_KEY, JSON.stringify(next))
      return next
    })
  }, [])

  // ── 保存设置 ──
  const saveSettings = (newSettings) => {
    setSettings(newSettings)
    localStorage.setItem(STORAGE_KEY, JSON.stringify(newSettings))
    setShowSettings(false)
  }

  // ── 确定当前展示的优先级状态 ──
  let heroState = 'absent' // 默认无人
  let heroIcon = ICONS.absent
  let heroText = '无人'
  let heroHint = ''
  let heroCardClass = ''

  if (!connected) {
    heroState = 'loading'
    heroIcon = ICONS.loading
    heroText = '正在连接雷达…'
  } else if (fallAlertActive) {
    // P0: 跌倒告警
    heroState = 'fall'
    heroIcon = ICONS.fall
    heroText = '跌倒告警'
    heroCardClass = 'bg-gradient-to-b from-red-50 to-white shadow-[0_4px_24px_rgba(255,59,48,0.15)]'
    if (fallSince) heroHint = `发生时间: ${formatClock(fallSince)}`
  } else if (stayAlertActive) {
    // P1: 长时间驻留
    heroState = 'stay'
    heroIcon = ICONS.stay
    heroText = '长时间驻留告警'
    heroCardClass = 'bg-gradient-to-b from-yellow-50 to-white shadow-[0_4px_24px_rgba(255,149,0,0.12)]'
    if (presenceSince) heroHint = `持续时间: ${formatDuration(Date.now() - presenceSince)}`
  } else if (presence) {
    // P2: 有人
    heroState = 'present'
    heroIcon = ICONS.present
    heroText = '有人'
    heroCardClass = 'bg-gradient-to-b from-green-50/60 to-white'
  } else {
    // 无人
    heroState = 'absent'
    heroIcon = ICONS.absent
    heroText = '无人'
  }

  return (
    <div className="p-4 space-y-4">
      {/* ===== Hero 卡片（右上角设置按钮） ===== */}
      <div className={`rounded-2xl p-6 text-center bg-white shadow-sm transition-all duration-500 relative ${heroCardClass}`}>
        <motion.button
          whileTap={{ scale: 0.9 }}
          onClick={() => setShowSettings(true)}
          className="absolute top-3 right-3 w-8 h-8 bg-white/80 rounded-full flex items-center justify-center shadow-sm text-gray-400 hover:text-gray-600"
        >
          <Settings size={16} />
        </motion.button>
        <div className="w-[120px] h-[120px] mx-auto mb-4">
          {heroIcon}
        </div>
        <p className="text-2xl font-bold tracking-tight mb-1"
           style={{
             color: heroState === 'fall' ? '#FF3B30'
                  : heroState === 'stay' ? '#FF9500'
                  : heroState === 'present' ? '#34C759'
                  : heroState === 'loading' ? '#8E8E93'
                  : '#AEAEB2'
           }}>
          {heroText}
        </p>
        {heroHint && (
          <p className={`text-sm mt-2 ${
            heroState === 'fall' ? 'text-red-400' : 'text-yellow-600'
          }`}>
            {heroHint}
          </p>
        )}
      </div>

      {/* ===== 监测详情 ===== */}
      <Card className="p-4">
        <h3 className="text-sm font-medium text-gray-500 mb-3">监测详情</h3>
        <div className="space-y-0">
          {/* 在场状态 */}
          <div className="flex items-center justify-between py-3 border-b border-gray-100">
            <div className="flex items-center gap-3">
              <div className="w-11 h-11 rounded-xl bg-blue-50 flex items-center justify-center text-blue-500">
                <svg viewBox="0 0 48 48" fill="none" className="w-7 h-7">
                  <circle cx="24" cy="14" r="6" fill="currentColor" opacity="0.9" />
                  <path d="M12 38c0-6.627 5.373-12 12-12s12 5.373 12 12" stroke="currentColor" strokeWidth="3" strokeLinecap="round" />
                </svg>
              </div>
              <span className="text-sm text-gray-700">在场状态</span>
            </div>
            <span className={`text-sm font-semibold ${presence ? 'text-green-500' : 'text-gray-400'}`}>
              {presence ? '有人' : '无人'}
            </span>
          </div>
          {/* 跌倒状态 */}
          <div className="flex items-center justify-between py-3 border-b border-gray-100">
            <div className="flex items-center gap-3">
              <div className="w-11 h-11 rounded-xl bg-red-50 flex items-center justify-center text-red-500">
                <svg viewBox="0 0 48 48" fill="none" className="w-7 h-7">
                  <circle cx="30" cy="10" r="5" fill="currentColor" />
                  <path d="M18 42l8-16 6 4 10-18" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" />
                </svg>
              </div>
              <span className="text-sm text-gray-700">跌倒状态</span>
            </div>
            <span className={`text-sm font-semibold ${(fallAlertActive || fallDetected) ? 'text-red-500' : 'text-green-500'}`}>
              {(fallAlertActive || fallDetected) ? '有' : '无'}
            </span>
          </div>
          {/* 长时间驻留 */}
          <div className="flex items-center justify-between py-3">
            <div className="flex items-center gap-3">
              <div className="w-11 h-11 rounded-xl bg-yellow-50 flex items-center justify-center text-yellow-500">
                <svg viewBox="0 0 48 48" fill="none" className="w-7 h-7">
                  <circle cx="24" cy="24" r="16" stroke="currentColor" strokeWidth="2.5" />
                  <path d="M24 14v12l8 5" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" />
                </svg>
              </div>
              <span className="text-sm text-gray-700">长时间驻留</span>
            </div>
            <span className={`text-sm font-semibold ${(stayAlertActive || stayDetected) ? 'text-yellow-500' : 'text-green-500'}`}>
              {(stayAlertActive || stayDetected) ? '有' : '无'}
            </span>
          </div>
        </div>
      </Card>

      {/* ===== 设置弹窗（居中） ===== */}
      <AnimatePresence>
        {showSettings && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/50 flex items-center justify-center z-50"
            onClick={() => setShowSettings(false)}
          >
            <motion.div
              initial={{ scale: 0.85, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.85, opacity: 0 }}
              transition={{ type: 'spring', duration: 0.3 }}
              className="bg-white rounded-2xl mx-4 w-full max-w-sm max-h-[80vh] overflow-y-auto"
              onClick={(e) => e.stopPropagation()}
            >
              <div className="p-5 pb-3 text-center">
                <h3 className="text-base font-semibold text-gray-800">设置</h3>
              </div>
              <div className="px-5 pb-5">
                <SettingsPanel
                  settings={settings}
                  onSave={saveSettings}
                />
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* ===== 告警记录 ===== */}
      <Card className="p-4">
        <h3 className="text-sm font-medium text-gray-500 mb-3">告警记录</h3>
        {alertHistory.length === 0 ? (
          <p className="text-center py-6 text-gray-300 text-sm">暂无告警记录</p>
        ) : (
          <div className="space-y-2 max-h-[248px] overflow-y-auto">
            {alertHistory.map((item, idx) => (
              <div key={idx} className="flex items-center gap-3 py-2.5 border-b border-gray-100 last:border-0">
                <span className="text-xs text-gray-400 font-mono flex-shrink-0">{item.time}</span>
                <span className="flex items-center gap-1.5 text-sm font-medium"
                   style={{ color: item.type === 'fall' ? '#FF3B30' : '#FF9500' }}>
                  <span className={`w-1.5 h-1.5 rounded-full ${item.type === 'fall' ? 'bg-red-500' : 'bg-yellow-500'}`} />
                  {item.event}
                </span>
              </div>
            ))}
          </div>
        )}
      </Card>
    </div>
  )
}

// ==================== 设置面板 ====================
const SettingsPanel = ({ settings, onSave }) => {
  const [fallDelay, setFallDelay] = useState(settings.fallDelay)
  const [stayDuration, setStayDuration] = useState(settings.stayDuration)

  return (
    <motion.div
      initial={{ opacity: 0, height: 0 }}
      animate={{ opacity: 1, height: 'auto' }}
      exit={{ opacity: 0, height: 0 }}
      className="mt-4 space-y-4 border-t border-gray-100 pt-4"
    >
      <div>
        <label className="block text-sm font-semibold text-gray-700 mb-2">跌倒告警延迟时间</label>
        <p className="text-xs text-gray-400 mb-3 leading-relaxed">
          设备检测到有人跌倒时，会继续进行一小段时间的监测，如监测老人是否自行起身
        </p>
        <div className="flex gap-2 flex-wrap">
          {[30, 60, 90, 120].map((delay) => (
            <motion.button
              key={delay}
              whileTap={{ scale: 0.95 }}
              onClick={() => setFallDelay(delay)}
              className={`px-4 py-2 rounded-xl text-sm font-medium transition-all ${
                fallDelay === delay
                  ? 'bg-primary text-white'
                  : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
              }`}
            >
              {delay}s
            </motion.button>
          ))}
        </div>
      </div>

      <div className="mt-6">
        <label className="block text-sm font-semibold text-gray-700 mb-2">长时间驻留多久后告警</label>
        <p className="text-xs text-gray-400 mb-3 leading-relaxed">
          老人持续驻留时长达到设定值时，设备将进行告警
        </p>
        <div className="flex gap-2 flex-wrap">
          {[5, 10, 15, 20].map((threshold) => (
            <motion.button
              key={threshold}
              whileTap={{ scale: 0.95 }}
              onClick={() => setStayDuration(threshold)}
              className={`px-4 py-2 rounded-xl text-sm font-medium transition-all ${
                stayDuration === threshold
                  ? 'bg-primary text-white'
                  : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
              }`}
            >
              {threshold}min
            </motion.button>
          ))}
        </div>
      </div>

      <motion.button
        whileTap={{ scale: 0.98 }}
        onClick={() => onSave({ fallDelay, stayDuration })}
        className="w-full py-2 bg-primary text-white rounded-xl text-sm font-medium"
      >
        保存
      </motion.button>
    </motion.div>
  )
}

export default FallDetectionTab