import { motion } from 'framer-motion'
import { Home, BarChart3, Grid3x3, User } from 'lucide-react'

const navItems = [
  { id: 'home', label: '首页', icon: Home },
  { id: 'stats', label: '统计', icon: BarChart3 },
  { id: 'function', label: '功能', icon: Grid3x3 },
  { id: 'profile', label: '我的', icon: User },
]

const BottomNav = ({ activeTab, setActiveTab }) => {
  return (
    <nav className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-100 safe-area-inset-bottom z-50">
      <div className="flex items-center justify-around h-14">
        {navItems.map((item) => {
          const isActive = activeTab === item.id
          const Icon = item.icon

          return (
            <motion.button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className="relative flex flex-col items-center justify-center w-full h-full transition-all duration-250"
              whileTap={{ scale: 0.9 }}
            >
              <div className="relative flex flex-col items-center">
                <motion.div
                  animate={{
                    scale: isActive ? 1.15 : 1,
                    y: isActive ? -2 : 0,
                  }}
                  transition={{ type: 'spring', stiffness: 300, damping: 20 }}
                >
                  <Icon
                    size={22}
                    strokeWidth={isActive ? 2.5 : 2}
                    className={isActive ? 'text-primary' : 'text-gray-500'}
                  />
                </motion.div>
                <motion.span
                  className="mt-0.5 text-xs font-medium"
                  animate={{
                    color: isActive ? '#007AFF' : '#9CA3AF',
                    fontWeight: isActive ? 600 : 400,
                  }}
                  transition={{ duration: 0.2 }}
                >
                  {item.label}
                </motion.span>
              </div>
            </motion.button>
          )
        })}
      </div>
    </nav>
  )
}

export default BottomNav
