import { useState, useEffect, useRef, useCallback } from 'react'
import { motion } from 'framer-motion'
import { Wifi, WifiOff } from 'lucide-react'
import {
  LineChart,
  Line,
  YAxis,
  Tooltip,
  ResponsiveContainer,
} from 'recharts'

// ==================== 工具函数 ====================
const generateBreathingWave = (t) => {
  const baseWave = Math.sin(t * 0.1) * 20 + 50
  const noise = (Math.random() - 0.5) * 10
  const breathing = Math.sin(t * 0.05) * 15
  return Math.max(0, Math.min(100, baseWave + noise + breathing))
}

const VitalSignsTab = () => {
  const [waveData, setWaveData] = useState([])
  const [isOnline, setIsOnline] = useState(true)
  const [isInBed, setIsInBed] = useState(true)
  const [isNormal, setIsNormal] = useState(true)
  const timeRef = useRef(0)
  const maxDataPoints = 50

  // 初始化数据
  useEffect(() => {
    const initial = []
    for (let i = 0; i < maxDataPoints; i++) {
      initial.push({ time: i, value: 50 })
    }
    setWaveData(initial)
  }, [])

  // 每500ms更新图表 + 每3秒模拟状态变化
  useEffect(() => {
    const chartInterval = setInterval(() => {
      timeRef.current += 0.5
      const newValue = generateBreathingWave(timeRef.current)
      setWaveData(prev => {
        const next = [...prev, { time: prev.length, value: newValue }]
        next.shift()
        return next
      })
    }, 500)

    const statusInterval = setInterval(() => {
      // 随机切换在线状态（10%概率）
      if (Math.random() < 0.1) {
        setIsOnline(prev => !prev)
      }
      // 随机切换在床状态（5%概率）
      if (Math.random() < 0.05) {
        setIsInBed(prev => !prev)
      }
      // 如果在床，随机切换生命体征状态（8%概率）
      if (Math.random() < 0.08) {
        setIsNormal(prev => !prev)
      }
    }, 3000)

    return () => {
      clearInterval(chartInterval)
      clearInterval(statusInterval)
    }
  }, [])

  // 点击切换在线状态
  const toggleOnline = useCallback(() => {
    setIsOnline(prev => !prev)
  }, [])

  // 点击切换在床状态
  const toggleInBed = useCallback(() => {
    setIsInBed(prev => !prev)
  }, [])

  // 点击切换生命体征状态
  const toggleNormal = useCallback(() => {
    if (isInBed) setIsNormal(prev => !prev)
  }, [isInBed])

  // 当前最新值
  const currentValue = waveData.length > 0 ? waveData[waveData.length - 1].value : 50

  return (
    <div className="p-4 space-y-4">
      {/* ===== 生命体征曲线 ===== */}
      <div className="bg-white rounded-card shadow-sm overflow-hidden">
        {/* Header */}
        <div className="bg-gradient-to-r from-[#667eea] to-[#764ba2] px-4 py-3">
          <div className="flex items-center justify-between">
            <h3 className="text-sm font-semibold text-white/90">生命体征曲线</h3>
            <motion.button
              whileTap={{ scale: 0.95 }}
              onClick={toggleOnline}
              className="flex items-center gap-1.5 bg-white/20 backdrop-blur-sm rounded-full px-3 py-1.5 text-xs text-white cursor-pointer"
            >
              {isOnline ? (
                <Wifi size={12} className="text-white" />
              ) : (
                <WifiOff size={12} className="text-white/60" />
              )}
              <span>{isOnline ? '在线' : '离线'}</span>
              <span className={`w-2 h-2 rounded-full ${isOnline ? 'bg-green-400 shadow-[0_0_0_2px_rgba(82,196,26,0.3)]' : 'bg-red-400 shadow-[0_0_0_2px_rgba(255,77,79,0.3)]'}`} />
            </motion.button>
          </div>
        </div>

        {/* Chart */}
        <div className="p-4">
          <div className="h-56 w-full bg-gray-50/80 rounded-xl border border-gray-100 p-3">
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={isOnline ? waveData : []} margin={{ top: 5, right: 5, left: 0, bottom: 0 }}>
                <YAxis
                  domain={[0, 100]}
                  ticks={[0, 20, 40, 60, 80, 100]}
                  tick={{ fontSize: 11, fill: '#999' }}
                  axisLine={false}
                  tickLine={false}
                  width={30}
                />
                <Tooltip
                  contentStyle={{
                    backgroundColor: 'rgba(0,0,0,0.8)',
                    border: 'none',
                    borderRadius: '6px',
                    fontSize: '12px',
                    color: '#fff',
                    padding: '8px 12px',
                  }}
                  formatter={[(value) => value.toFixed(1), '压力值']}
                  labelStyle={{ display: 'none' }}
                />
                <Line
                  type="monotone"
                  dataKey="value"
                  stroke="#667eea"
                  strokeWidth={2}
                  dot={false}
                  isAnimationActive={false}
                  activeDot={{ r: 4, fill: '#667eea', stroke: '#fff', strokeWidth: 2 }}
                  fill="rgba(102, 126, 234, 0.1)"
                />
              </LineChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* ===== 检测结果 ===== */}
      <div className="bg-white rounded-card shadow-sm p-4">
        <h3 className="text-sm font-semibold text-gray-700 mb-3 pl-3 border-l-4 border-[#667eea] leading-tight">
          检测结果
        </h3>
        <div className="bg-gray-50/80 rounded-xl border border-gray-100 p-4">
          {/* 是否在床 */}
          <motion.div
            whileTap={{ scale: 0.98 }}
            onClick={toggleInBed}
            className="flex items-center justify-between py-3 border-b border-gray-100 cursor-pointer"
          >
            <span className="text-sm font-medium text-gray-600">是否在床</span>
            <span className={`text-sm font-semibold px-4 py-1.5 rounded-full ${
              isInBed
                ? 'bg-blue-50 text-blue-500'
                : 'bg-red-50 text-red-500'
            }`}>
              {isInBed ? '是' : '否'}
            </span>
          </motion.div>

          {/* 生命体征 */}
          <motion.div
            whileTap={{ scale: 0.98 }}
            onClick={toggleNormal}
            className={`flex items-center justify-between py-3 cursor-pointer ${
              isInBed ? '' : 'opacity-40'
            }`}
          >
            <span className="text-sm font-medium text-gray-600">生命体征</span>
            {isInBed ? (
              <span className={`text-sm font-semibold px-4 py-1.5 rounded-full ${
                isNormal
                  ? 'bg-green-50 text-green-500'
                  : 'bg-orange-50 text-orange-500'
              }`}>
                {isNormal ? '正常' : '异常'}
              </span>
            ) : (
              <span className="text-sm text-gray-300">—</span>
            )}
          </motion.div>
        </div>
      </div>
    </div>
  )
}

export default VitalSignsTab