import { motion } from 'framer-motion'
import { Volume2, MousePointerClick, Phone, Smartphone } from 'lucide-react'
import Card from '../common/Card'
import { mockRescueEvents } from '../../utils/mockData'

const eventIcons = {
  pat: MousePointerClick,
  sound: Volume2,
  button: Smartphone,
}

const eventColors = {
  pat: 'text-orange-500',
  sound: 'text-blue-500',
  button: 'text-green-500',
}

const RescueTab = () => {
  const filteredEvents = mockRescueEvents.filter(e => e.type !== 'cry')

  return (
    <div className="p-4 space-y-4">
      <Card className="p-4">
        <div className="space-y-3">
          {filteredEvents.map((event, index) => {
            const Icon = eventIcons[event.type] || Phone
            const iconColor = eventColors[event.type] || 'text-gray-500'

            return (
              <motion.div
                key={event.id}
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: index * 0.1 }}
                className="border-b border-gray-100 pb-3 last:border-0 last:pb-0"
              >
                <div className="flex items-center gap-3">
                  <div className="w-8 h-8 rounded-full bg-gray-50 flex items-center justify-center flex-shrink-0">
                    <Icon size={18} className={iconColor} />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center justify-between">
                      <p className="font-medium text-gray-800">{event.title}</p>
                      <span className={`text-xs px-2 py-0.5 rounded-full flex-shrink-0 ml-2 ${
                        event.status === 'answered'
                          ? 'bg-green-100 text-green-600'
                          : 'bg-red-100 text-danger'
                      }`}>
                        {event.status === 'answered' ? '已接听' : '无人接听'}
                      </span>
                    </div>
                    <p className="text-sm text-gray-500 mt-1">
                      {event.time} · {event.location}
                    </p>
                    {event.status === 'answered' && event.answeredBy && (
                      <p className="text-xs text-gray-400 mt-0.5">
                        接听人: {event.answeredBy}{event.phone ? ` (${event.phone})` : ''}
                      </p>
                    )}
                  </div>
                </div>
              </motion.div>
            )
          })}
        </div>
      </Card>
    </div>
  )
}

export default RescueTab