import { useState } from 'react'
import { motion } from 'framer-motion'
import { ArrowLeft, Trash2, UserCheck, UserPlus } from 'lucide-react'
import Card from '../components/common/Card'

const FamilyMembersPage = ({ onBack }) => {
  const [members, setMembers] = useState([
    { id: 1, nickname: '张三三张三三张三三三张三三', phone: '130****5308', isAdmin: true },
    { id: 2, nickname: '李华', phone: '130****5308', isAdmin: false },
    { id: 3, nickname: '张强', phone: '130****5308', isAdmin: false },
  ])

  const handleRemove = (id) => {
    setMembers(members.filter(m => m.id !== id))
  }

  return (
    <div className="min-h-screen bg-gray-50 pt-12 pb-16">
      {/* Header */}
      <div className="px-4 pt-4 pb-4 flex items-center justify-center relative bg-white">
        <motion.button
          whileTap={{ scale: 0.9 }}
          onClick={onBack}
          className="absolute left-4"
        >
          <ArrowLeft size={24} className="text-gray-600" />
        </motion.button>
        <h1 className="text-lg font-semibold text-gray-800">家庭成员</h1>
      </div>

      <div className="px-4 py-6 space-y-3">
        {/* Member Cards */}
        {members.map((member, index) => (
          <motion.div
            key={member.id}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: index * 0.05 }}
          >
            <Card className="p-4">
              {/* Top row: nickname, tags, actions */}
              <div className="flex items-center justify-between mb-3">
                <div className="flex items-center gap-2 min-w-0">
                  <span className="text-sm text-gray-500 flex-shrink-0">昵称：</span>
                  <span className="text-sm font-medium text-gray-800 truncate">
                    {member.nickname}
                  </span>
                </div>
                <div className="flex items-center gap-2 flex-shrink-0 ml-2">
                  {member.isAdmin && (
                    <span className="text-xs px-2 py-0.5 bg-yellow-100 text-yellow-600 rounded-full">
                      管理员
                    </span>
                  )}
                  <motion.button
                    whileTap={{ scale: 0.95 }}
                    className="text-xs text-primary font-medium flex items-center gap-1"
                  >
                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" className="w-3.5 h-3.5">
                      <path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7" />
                      <path d="M18.5 2.5a2.121 2.121 0 1 3 3L12 13l-3 1 1-3 9.5-9.5z" />
                    </svg>
                    编辑
                  </motion.button>
                </div>
              </div>

              {/* Phone */}
              <div className="text-sm text-gray-600 mb-3">
                电话：{member.phone}
              </div>

              {/* Bottom row: actions for non-admin */}
              {!member.isAdmin && (
                <div className="flex items-center justify-end gap-4 pt-3 border-t border-gray-100">
                  <motion.button
                    whileTap={{ scale: 0.95 }}
                    onClick={() => handleRemove(member.id)}
                    className="flex items-center gap-1 text-sm text-gray-600"
                  >
                    <Trash2 size={14} />
                    移除
                  </motion.button>
                  <motion.button
                    whileTap={{ scale: 0.95 }}
                    className="flex items-center gap-1 text-sm text-gray-600"
                  >
                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" className="w-4 h-4">
                      <path d="M7 16V4m0 0L3 8m4-4l4 4M17 8v12m0 0l4-4m-4 4l-4-4" />
                    </svg>
                    转移权限
                  </motion.button>
                </div>
              )}
            </Card>
          </motion.div>
        ))}

        {/* Invite Button */}
        <motion.button
          whileTap={{ scale: 0.98 }}
          className="w-full py-3.5 rounded-2xl text-white font-medium mt-6 flex items-center justify-center gap-2"
          style={{ backgroundColor: '#FFD6B3' }}
        >
          <UserPlus size={20} />
          邀请好友
        </motion.button>

        {/* Footer text */}
        <p className="text-xs text-gray-400 text-center mt-4">
          家庭成员登录小程序后，可查看老人的相关信息
        </p>
      </div>
    </div>
  )
}

export default FamilyMembersPage