// ==================== Vital Signs (Bed Pad) ====================

/**
 * Generates a random wave data point for vital signs.
 * Voltage range: 1200~2500mV (in-bed), simulating breathing/heart rate.
 */
const generateWavePoint = (index, baseVoltage = 1800) => {
  const time = index * 200 // 200ms intervals
  // Simulate breathing wave (slow, ~4-6 second period)
  const breathing = Math.sin(index * 0.05) * 80
  // Simulate heart rate wave (faster, ~1 second period)
  const heartRate = Math.sin(index * 0.3) * 30
  // Add some random noise
  const noise = (Math.random() - 0.5) * 20
  const voltage = baseVoltage + breathing + heartRate + noise

  return {
    time,
    voltage: Math.round(Math.max(1200, Math.min(2500, voltage))),
  }
}

/**
 * Generates an array of vital signs wave data points.
 * @param {number} count - Number of data points to generate
 * @param {number} baseVoltage - Base voltage level (default: 1800)
 * @returns {Array<{time: number, voltage: number}>}
 */
export const generateVitalSigns = (count = 50, baseVoltage = 1800) => {
  return Array.from({ length: count }, (_, i) => generateWavePoint(i, baseVoltage))
}

/**
 * Generates real-time vital signs data by appending a new point to existing data.
 * @param {Array} existingData - Existing wave data
 * @returns {Array} Updated wave data with new point
 */
export const updateVitalSigns = (existingData = []) => {
  const lastIndex = existingData.length - 1
  const baseVoltage = 1800 + (Math.random() - 0.5) * 100
  const newPoint = generateWavePoint(lastIndex + 1, baseVoltage)
  return [...existingData.slice(-49), newPoint]
}

/**
 * Determines if person is in bed based on voltage.
 * @param {number} voltage - Current voltage reading
 * @returns {{inBed: boolean, status: 'in-bed' | 'out-of-bed'}}
 */
export const getInBedStatus = (voltage) => {
  if (voltage >= 1200 && voltage <= 2500) {
    return { inBed: true, status: 'in-bed' }
  }
  if (voltage > 2600) {
    return { inBed: false, status: 'out-of-bed' }
  }
  return { inBed: false, status: 'out-of-bed' }
}

/**
 * Determines vital signs health status.
 * Normal: 5 min in bed with voltage range > 15mV
 * Abnormal: 30 min in bed with voltage range < 15mV
 * @param {Array} data - Wave data points
 * @param {number} minutesInBed - Minutes spent in bed
 * @returns {{status: 'normal' | 'abnormal', range: number}}
 */
export const getVitalSignsStatus = (data, minutesInBed = 5) => {
  if (data.length < 2) return { status: 'normal', range: 0 }

  const voltages = data.map((d) => d.voltage)
  const min = Math.min(...voltages)
  const max = Math.max(...voltages)
  const range = max - min

  if (minutesInBed >= 30 && range < 15) {
    return { status: 'abnormal', range }
  }
  if (minutesInBed >= 5 && range > 15) {
    return { status: 'normal', range }
  }
  return { status: 'normal', range }
}

// ==================== Fall Detection (Radar) ====================

/**
 * Fall alarm state types:
 * - 'normal': No events
 * - 'suspected': Fall suspected, countdown active
 * - 'alarm': Fall confirmed, alarm active
 * - 'lingering': Long stay warning
 */
export const FALL_ALARM_STATES = {
  NORMAL: 'normal',
  SUSPECTED: 'suspected',
  ALARM: 'alarm',
  LINGERING: 'lingering',
}

/**
 * Simulates the fall detection alarm flow.
 * 1. Detects "suspected fall" -> starts countdown (default 30s)
 * 2. If no "standing/activity" detected during countdown -> triggers alarm
 * 3. Alarm state persists for 5 minutes then resets
 */
export class FallDetectionSimulator {
  constructor(onStateChange) {
    this.state = FALL_ALARM_STATES.NORMAL
    this.countdown = 0
    this.alarmTimer = null
    this.countdownTimer = null
    this.onStateChange = onStateChange
  }

  // Start the fall detection process
  startFallDetection(delaySeconds = 30) {
    this.setState(FALL_ALARM_STATES.SUSPECTED)
    this.countdown = delaySeconds

    this.countdownTimer = setInterval(() => {
      this.countdown -= 1
      if (this.countdown <= 0) {
        clearInterval(this.countdownTimer)
        this.setState(FALL_ALARM_STATES.ALARM)
        this.startAlarmTimer()
      }
    }, 1000)
  }

  // Cancel suspected fall (person stood up or activity detected)
  cancelFallDetection() {
    clearInterval(this.countdownTimer)
    this.countdown = 0
    this.setState(FALL_ALARM_STATES.NORMAL)
  }

  // Start the 5-minute alarm persistence timer
  startAlarmTimer() {
    this.alarmTimer = setTimeout(() => {
      this.setState(FALL_ALARM_STATES.NORMAL)
    }, 5 * 60 * 1000) // 5 minutes
  }

  // Trigger lingering warning
  triggerLingering(durationMinutes = 10) {
    this.setState(FALL_ALARM_STATES.LINGERING)
    this.alarmTimer = setTimeout(() => {
      this.setState(FALL_ALARM_STATES.NORMAL)
    }, 5 * 60 * 1000)
  }

  setState(newState) {
    this.state = newState
    if (this.onStateChange) {
      this.onStateChange(newState, this.countdown)
    }
  }

  destroy() {
    clearInterval(this.countdownTimer)
    clearTimeout(this.alarmTimer)
  }
}

