import { useState, useEffect } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { ChevronDown, X } from 'lucide-react'
import { mockDevices } from '../utils/mockData'

const IntercomDialog = ({ isOpen, onClose, onSelectDevice }) => {
  const [isTalking, setIsTalking] = useState(false)
  const [selectedDevice, setSelectedDevice] = useState(mockDevices[0])
  const [showDeviceList, setShowDeviceList] = useState(false)

  // 重置状态当弹窗关闭
  useEffect(() => {
    if (!isOpen) {
      setIsTalking(false)
      setShowDeviceList(false)
    }
  }, [isOpen])

  const handleToggleTalk = () => {
    setIsTalking(!isTalking)
  }

  const handleSelectDevice = (device) => {
    setSelectedDevice(device)
    setShowDeviceList(false)
    onSelectDevice?.(device)
  }

  return (
    <AnimatePresence>
      {isOpen && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 bg-black/60 flex items-center justify-center z-50 p-4"
          onClick={onClose}
        >
          <motion.div
            initial={{ scale: 0.9, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            exit={{ scale: 0.9, opacity: 0 }}
            transition={{ type: 'spring', duration: 0.3 }}
            className="bg-white rounded-3xl p-8 w-full max-w-sm text-center"
            onClick={(e) => e.stopPropagation()}
          >
            {/* 顶部文字 */}
            <p className="text-base font-medium text-gray-800 mb-6">
              {isTalking ? '在此点击可结束对讲' : '点击可与设备进行对讲'}
            </p>

            {/* 麦克风图标 */}
            <div className="flex justify-center mb-6">
              <motion.button
                whileTap={{ scale: 0.95 }}
                onClick={handleToggleTalk}
                className="w-24 h-24 rounded-full flex items-center justify-center"
                style={{ backgroundColor: '#E5F3FF' }}
              >
                <svg viewBox="0 0 24 24" fill="none" stroke="#007AFF" strokeWidth="2" className="w-12 h-12">
                  <rect x="9" y="1" width="6" height="12" rx="3" />
                  <path d="M19 10v1a7 7 0 0 1-14 0v-1" />
                  <line x1="12" y1="19" x2="12" y2="23" />
                  <line x1="8" y1="23" x2="16" y2="23" />
                </svg>
                {isTalking && (
                  <div className="absolute inset-0 flex items-center justify-center">
                    {[
                      { delay: 0, height: 10 },
                      { delay: 0.15, height: 18 },
                      { delay: 0.3, height: 10 },
                      { delay: 0.45, height: 14 },
                      { delay: 0.6, height: 10 },
                    ].map((item, i) => (
                      <motion.div
                        key={i}
                        className="w-1.5 bg-blue-500 rounded-full mx-0.5"
                        animate={{
                          height: [item.height, item.height + 6, item.height - 2, item.height],
                          opacity: [0.7, 1, 0.7, 1],
                        }}
                        transition={{
                          duration: 1.2,
                          delay: item.delay,
                          repeat: Infinity,
                          ease: 'easeInOut',
                        }}
                      />
                    ))}
                  </div>
                )}
              </motion.button>
            </div>

            {/* 设备选择器 */}
            <motion.button
              whileTap={{ scale: 0.98 }}
              onClick={() => setShowDeviceList(true)}
              className="flex items-center justify-center gap-1.5 text-sm text-gray-700 mx-auto"
            >
              <span>对讲设备: {selectedDevice.name}</span>
              <ChevronDown size={16} className="text-gray-400" />
            </motion.button>

            {/* 设备列表底部弹窗 */}
            <AnimatePresence>
              {showDeviceList && (
                <motion.div
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  exit={{ opacity: 0 }}
                  className="fixed inset-0 bg-black/40 flex items-end z-50"
                  onClick={() => setShowDeviceList(false)}
                >
                  <motion.div
                    initial={{ y: '100%' }}
                    animate={{ y: 0 }}
                    exit={{ y: '100%' }}
                    transition={{ type: 'spring', duration: 0.3 }}
                    className="bg-white rounded-t-3xl w-full max-w-sm mx-auto"
                    onClick={(e) => e.stopPropagation()}
                  >
                    {/* Header */}
                    <div className="flex items-center justify-between px-5 py-4 border-b border-gray-100">
                      <motion.button
                        whileTap={{ scale: 0.95 }}
                        onClick={() => setShowDeviceList(false)}
                        className="text-sm text-gray-500"
                      >
                        取消
                      </motion.button>
                      <h3 className="text-base font-semibold text-gray-800">选择设备</h3>
                      <motion.button
                        whileTap={{ scale: 0.95 }}
                        onClick={() => setShowDeviceList(false)}
                        className="text-sm font-medium"
                        style={{ color: '#007AFF' }}
                      >
                        确认
                      </motion.button>
                    </div>

                    {/* Device List */}
                    <div className="p-4 space-y-2">
                      {mockDevices
                        .filter(d => d.status === 'online')
                        .map(device => (
                          <motion.button
                            key={device.id}
                            whileTap={{ scale: 0.98 }}
                            onClick={() => handleSelectDevice(device)}
                            className={`w-full py-3 rounded-xl text-sm font-medium border ${
                              selectedDevice.id === device.id
                                ? 'border-blue-500 text-blue-500 bg-blue-50'
                                : 'border-gray-200 text-gray-700 bg-white'
                            }`}
                          >
                            {device.name}
                          </motion.button>
                        ))}
                    </div>
                  </motion.div>
                </motion.div>
              )}
            </AnimatePresence>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  )
}

export default IntercomDialog