import { useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import {
  ArrowLeft,
  Plus,
  Clock,
  Play,
  Trash2,
  Bell,
} from 'lucide-react'
import { mockMedications, mockDevices } from '../utils/mockData'

const MedicationReminder = ({ onBack }) => {
  const [medications, setMedications] = useState(mockMedications)
  const [showForm, setShowForm] = useState(false)
  const [editingId, setEditingId] = useState(null)

  const handleDelete = (id) => {
    setMedications(medications.filter((m) => m.id !== id))
  }

  const handleToggle = (id) => {
    setMedications(
      medications.map((m) =>
        m.id === id ? { ...m, enabled: !m.enabled } : m
      )
    )
  }

  const handleSave = (data) => {
    if (editingId) {
      setMedications(medications.map((m) => (m.id === editingId ? { ...m, ...data } : m)))
      setEditingId(null)
    } else {
      setMedications([...medications, { ...data, id: `med-${Date.now()}` }])
    }
    setShowForm(false)
  }

  return (
    <div className="min-h-screen bg-gray-50 pt-12 pb-16">
      {/* Header */}
      <div className="px-4 pt-4 pb-4 flex items-center justify-center relative bg-white">
        <motion.button
          whileTap={{ scale: 0.9 }}
          onClick={onBack}
          className="w-8 h-8 bg-white rounded-full flex items-center justify-center shadow-card absolute left-4"
        >
          <ArrowLeft size={20} className="text-gray-600" />
        </motion.button>
        <h1 className="text-lg font-semibold text-gray-800">用药提醒</h1>
        <motion.button
          whileTap={{ scale: 0.9 }}
          onClick={() => {
            setEditingId(null)
            setShowForm(true)
          }}
          className="absolute right-4 text-sm font-bold"
          style={{ color: '#007AFF' }}
        >
          + 新建
        </motion.button>
      </div>

      {/* Medication List */}
      <div className="px-4 space-y-3">
        {medications.map((med, index) => (
          <motion.div
            key={med.id}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: index * 0.08 }}
            className="bg-white rounded-2xl p-4 shadow-sm"
          >
            <div className="flex items-start justify-between mb-3">
              <div className="flex-1">
                <p className="text-base font-medium text-gray-800">{med.name}</p>
              </div>
              <div className="flex items-center gap-3">
                <motion.button
                  whileTap={{ scale: 0.9 }}
                  onClick={() => handleDelete(med.id)}
                  className="w-7 h-7 rounded-full flex items-center justify-center"
                  style={{ backgroundColor: '#FEE2E2' }}
                >
                  <Trash2 size={14} className="text-red-500" />
                </motion.button>
                <motion.button
                  whileTap={{ scale: 0.95 }}
                  onClick={() => handleToggle(med.id)}
                  className={`relative inline-flex h-5 w-9 items-center rounded-full transition-colors ${
                    med.enabled ? 'bg-blue-500' : 'bg-gray-300'
                  }`}
                >
                  <span
                    className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
                      med.enabled ? 'translate-x-5' : 'translate-x-1'
                    }`}
                  />
                </motion.button>
              </div>
            </div>

            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <p className="text-4xl font-bold tracking-tight text-gray-800">
                  {med.times[0] || '00:00'}
                </p>
                <motion.button
                  whileTap={{ scale: 0.9 }}
                  className="w-8 h-8 rounded-lg flex items-center justify-center"
                  style={{ backgroundColor: '#E5E7EB' }}
                >
                  <Play size={14} className="text-gray-500 ml-0.5" />
                </motion.button>
              </div>
            </div>

            <div className="flex items-center justify-between mt-3">
              <div className="flex items-center gap-2 text-sm text-gray-500">
                <Clock size={14} />
                <span>
                  {med.repeat === 'daily' ? '每天' : <>{med.date || '2025-12-25'} 仅1次</>}
                </span>
                <span className="text-gray-300">|</span>
                <span>{med.location || med.device}</span>
              </div>
              <motion.button
                whileTap={{ scale: 0.9 }}
                onClick={() => {
                  setEditingId(med.id)
                  setShowForm(true)
                }}
                className="text-sm font-medium"
                style={{ color: '#007AFF' }}
              >
                编辑
              </motion.button>
            </div>
          </motion.div>
        ))}

        {medications.length === 0 && (
          <div className="text-center py-16 text-gray-400">
            <Bell size={40} className="mx-auto mb-3 text-gray-300" />
            <p>暂无用药提醒</p>
          </div>
        )}
      </div>

      {/* Form Modal */}
      <AnimatePresence>
        {showForm && (
          <MedicationForm
            initialData={editingId ? medications.find((m) => m.id === editingId) : null}
            onSave={handleSave}
            onClose={() => {
              setShowForm(false)
              setEditingId(null)
            }}
          />
        )}
      </AnimatePresence>
    </div>
  )
}

const MedicationForm = ({ initialData, onSave, onClose }) => {
  const [name, setName] = useState(initialData?.name || '')
  const [device, setDevice] = useState(initialData?.device || '')
  const [date, setDate] = useState(initialData ? '2025-12-25' : '')
  const [time, setTime] = useState(initialData?.times?.[0] || '08:00')
  const [repeat, setRepeat] = useState(initialData?.repeat || 'daily')
  const [voiceType, setVoiceType] = useState('default')

  const handleSave = () => {
    if (!name || !device) return
    onSave({
      name,
      device,
      times: [time],
      repeat,
      voice: voiceType === 'default' ? '默认语音' : '自定义语音',
      enabled: true,
    })
  }

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="fixed inset-0 bg-black/40 flex items-center justify-center z-50 p-4"
      onClick={onClose}
    >
      <motion.div
        initial={{ scale: 0.95, opacity: 0 }}
        animate={{ scale: 1, opacity: 1 }}
        exit={{ scale: 0.95, opacity: 0 }}
        className="bg-white rounded-2xl w-full max-w-sm max-h-[85vh] overflow-y-auto"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="flex items-center justify-between px-5 py-4 border-b border-gray-100">
          <motion.button whileTap={{ scale: 0.9 }} onClick={onClose} className="text-gray-400">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" className="w-5 h-5">
              <path d="M15 18l-6-6 6-6" />
            </svg>
          </motion.button>
          <h2 className="text-base font-semibold text-gray-800">创建用药提醒</h2>
          <div className="w-5" />
        </div>

        <div className="p-5 space-y-5">
          {/* 设备 */}
          <FormRow label="设备" placeholder="点击选择提醒设备" icon="device" value={device} onChange={setDevice} />
          {/* 日期 */}
          <FormRow label="日期" placeholder="点击选择提醒日期" icon="calendar" value={date} onChange={setDate} type="date" />
          {/* 时间 */}
          <FormRow label="时间" placeholder="点击选择提醒时间" icon="clock" value={time} onChange={setTime} type="time" />

          {/* 重复 */}
          <div>
            <label className="block text-sm text-gray-600 mb-2">重复</label>
            <div className="flex gap-3">
              {[
                { value: 'once', label: '仅1次' },
                { value: 'daily', label: '每天' },
              ].map((item) => (
                <label key={item.value} className="flex items-center gap-2 cursor-pointer">
                  <div className="w-4 h-4 rounded-full border-2 flex items-center justify-center"
                    style={{ borderColor: repeat === item.value ? '#007AFF' : '#D1D5DB' }}>
                    {repeat === item.value && <div className="w-2 h-2 rounded-full bg-primary" />}
                  </div>
                  <span className="text-sm text-gray-700">{item.label}</span>
                </label>
              ))}
            </div>
          </div>

          {/* 提醒语音 */}
          <div>
            <label className="block text-sm text-gray-600 mb-2">提醒语音</label>
            <div className="flex gap-3">
              {[
                { value: 'default', label: '默认语音' },
                { value: 'custom', label: '自己录制' },
              ].map((item) => (
                <label key={item.value} className="flex items-center gap-2 cursor-pointer">
                  <div className="w-4 h-4 rounded-full border-2 flex items-center justify-center"
                    style={{ borderColor: voiceType === item.value ? '#007AFF' : '#D1D5DB' }}>
                    {voiceType === item.value && <div className="w-2 h-2 rounded-full bg-primary" />}
                  </div>
                  <span className="text-sm text-gray-700">{item.label}</span>
                </label>
              ))}
            </div>
          </div>

          {/* 语音播放条 */}
          <div className="flex items-center gap-3">
            <div className="flex-1 h-12 rounded-xl flex items-center px-4" style={{ backgroundColor: 'rgba(251,146,60,0.9)' }}>
              <Bell size={18} className="text-white mr-3" />
              <div className="flex-1 h-1 bg-white/30 rounded-full overflow-hidden">
                <div className="h-full w-2/3 bg-white rounded-full" />
              </div>
            </div>
            <motion.button
              whileTap={{ scale: 0.95 }}
              onClick={() => {}}
              className="w-10 h-10 rounded-full flex items-center justify-center"
              style={{ backgroundColor: '#007AFF' }}
            >
              <Play size={16} className="text-white ml-0.5" />
            </motion.button>
          </div>

          {/* 保存 */}
          <motion.button
            whileTap={{ scale: 0.98 }}
            onClick={handleSave}
            disabled={!name || !device}
            className="w-full py-3 rounded-xl text-white font-medium disabled:bg-gray-300 disabled:text-gray-500"
            style={{ backgroundColor: name && device ? '#007AFF' : '#D1D5DB' }}
          >
            保存
          </motion.button>
        </div>
      </motion.div>
    </motion.div>
  )
}

const FormRow = ({ label, placeholder, icon, value, onChange, type = 'text' }) => {
  const icons = {
    device: <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" className="w-5 h-5 text-gray-400"><rect x="2" y="6" width="20" height="12" rx="2"/><path d="M6 10h.01M6 14h.01"/></svg>,
    calendar: <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" className="w-5 h-5 text-gray-400"><rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/></svg>,
    clock: <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" className="w-5 h-5 text-gray-400"><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></svg>,
  }

  return (
    <div>
      <label className="block text-sm text-gray-600 mb-2">{label}</label>
      <div className="flex items-center gap-3 px-3 py-2.5 bg-gray-50 rounded-xl border border-gray-100">
        <span className="text-sm text-gray-500 flex-1">{value || placeholder}</span>
        {icons[icon]}
      </div>
    </div>
  )
}

export default MedicationReminder