import { useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { ChevronDown, Plus, User, Phone, MapPin, Calendar, Droplet, AlertCircle, Users, Trash2 } from 'lucide-react'
import Drawer from './common/Drawer'
import { mockFamilies, mockFamily } from '../utils/mockData'

const FamilySelector = ({ currentFamily, onFamilyChange }) => {
  const [drawerOpen, setDrawerOpen] = useState(false)
  const [createMode, setCreateMode] = useState(false)
  const [formData, setFormData] = useState({
    name: '',
    elderName: '',
    elderAge: '',
    elderPhone: '',
    elderRegion: '',
    bloodType: '',
    allergies: '',
    medicalHistory: '',
    emergencyName: '',
    emergencyPhone: '',
  })

  const handleCreate = () => {
    setCreateMode(true)
  }

  const handleSave = () => {
    if (!formData.name || !formData.elderName) return
    const newFamily = {
      id: `family-${Date.now()}`,
      name: formData.name,
      members: 1,
    }
    onFamilyChange(newFamily)
    setCreateMode(false)
    setDrawerOpen(false)
    setFormData({
      name: '',
      elderName: '',
      elderAge: '',
      elderPhone: '',
      elderRegion: '',
      bloodType: '',
      allergies: '',
      medicalHistory: '',
      emergencyName: '',
      emergencyPhone: '',
    })
  }

  const handleInputChange = (field, value) => {
    setFormData({ ...formData, [field]: value })
  }

  const renderCreateForm = () => (
    <div className="space-y-4">
      <div>
        <label className="block text-sm font-medium text-gray-700 mb-1">家庭名称</label>
        <input
          type="text"
          value={formData.name}
          onChange={(e) => handleInputChange('name', e.target.value)}
          className="w-full px-3 py-2 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary"
          placeholder="请输入家庭名称"
        />
      </div>

      <div className="border-t border-gray-100 pt-4">
        <h4 className="text-sm font-medium text-gray-700 mb-3 flex items-center gap-2">
          <User size={16} />
          老人信息
        </h4>
        <div className="space-y-3">
          <div>
            <label className="block text-sm text-gray-600 mb-1">姓名</label>
            <input
              type="text"
              value={formData.elderName}
              onChange={(e) => handleInputChange('elderName', e.target.value)}
              className="w-full px-3 py-2 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary/20"
              placeholder="请输入姓名"
            />
          </div>
          <div>
            <label className="block text-sm text-gray-600 mb-1">年龄</label>
            <input
              type="number"
              value={formData.elderAge}
              onChange={(e) => handleInputChange('elderAge', e.target.value)}
              className="w-full px-3 py-2 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary/20"
              placeholder="请输入年龄"
            />
          </div>
          <div>
            <label className="block text-sm text-gray-600 mb-1">电话</label>
            <input
              type="tel"
              value={formData.elderPhone}
              onChange={(e) => handleInputChange('elderPhone', e.target.value)}
              className="w-full px-3 py-2 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary/20"
              placeholder="请输入电话"
            />
          </div>
          <div>
            <label className="block text-sm text-gray-600 mb-1">地区</label>
            <input
              type="text"
              value={formData.elderRegion}
              onChange={(e) => handleInputChange('elderRegion', e.target.value)}
              className="w-full px-3 py-2 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary/20"
              placeholder="请输入地区"
            />
          </div>
          <div>
            <label className="block text-sm text-gray-600 mb-1">血型</label>
            <select
              value={formData.bloodType}
              onChange={(e) => handleInputChange('bloodType', e.target.value)}
              className="w-full px-3 py-2 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary/20"
            >
              <option value="">请选择</option>
              <option value="A">A 型</option>
              <option value="B">B 型</option>
              <option value="AB">AB 型</option>
              <option value="O">O 型</option>
            </select>
          </div>
          <div>
            <label className="block text-sm text-gray-600 mb-1">过敏史</label>
            <input
              type="text"
              value={formData.allergies}
              onChange={(e) => handleInputChange('allergies', e.target.value)}
              className="w-full px-3 py-2 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary/20"
              placeholder="请输入过敏史，无请填'无'"
            />
          </div>
          <div>
            <label className="block text-sm text-gray-600 mb-1">病史</label>
            <input
              type="text"
              value={formData.medicalHistory}
              onChange={(e) => handleInputChange('medicalHistory', e.target.value)}
              className="w-full px-3 py-2 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary/20"
              placeholder="请输入病史"
            />
          </div>
        </div>
      </div>

      <div className="border-t border-gray-100 pt-4">
        <h4 className="text-sm font-medium text-gray-700 mb-3 flex items-center gap-2">
          <Phone size={16} />
          紧急联系人
        </h4>
        <div className="space-y-3">
          <div>
            <label className="block text-sm text-gray-600 mb-1">姓名</label>
            <input
              type="text"
              value={formData.emergencyName}
              onChange={(e) => handleInputChange('emergencyName', e.target.value)}
              className="w-full px-3 py-2 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary/20"
              placeholder="请输入联系人姓名"
            />
          </div>
          <div>
            <label className="block text-sm text-gray-600 mb-1">电话</label>
            <input
              type="tel"
              value={formData.emergencyPhone}
              onChange={(e) => handleInputChange('emergencyPhone', e.target.value)}
              className="w-full px-3 py-2 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary/20"
              placeholder="请输入联系电话"
            />
          </div>
        </div>
      </div>

      <div className="pt-4 border-t border-gray-100">
        <motion.button
          whileTap={{ scale: 0.98 }}
          onClick={handleSave}
          className="w-full py-3 bg-primary text-white rounded-xl font-medium"
        >
          保存
        </motion.button>
      </div>
    </div>
  )

  const renderFamilyList = () => (
    <div className="space-y-3">
      {mockFamilies.map((family) => (
        <motion.div
          key={family.id}
          whileTap={{ scale: 0.98 }}
          onClick={() => {
            onFamilyChange(family)
            setDrawerOpen(false)
          }}
          className={`p-3 rounded-xl border transition-all cursor-pointer ${
            currentFamily?.id === family.id
              ? 'border-primary bg-primary/5'
              : 'border-gray-200 hover:border-gray-300'
          }`}
        >
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-gray-100 rounded-full flex items-center justify-center">
                <Users size={20} className="text-gray-500" />
              </div>
              <div>
                <p className="font-medium text-gray-800">{family.name}</p>
                <p className="text-sm text-gray-500">{family.members} 位成员</p>
              </div>
            </div>
            {currentFamily?.id === family.id && (
              <div className="w-2 h-2 bg-primary rounded-full" />
            )}
          </div>
        </motion.div>
      ))}

      <motion.div
        whileTap={{ scale: 0.98 }}
        onClick={handleCreate}
        className="p-3 rounded-xl border border-dashed border-gray-300 hover:border-primary hover:bg-primary/5 transition-all cursor-pointer flex items-center justify-center gap-2"
      >
        <Plus size={20} className="text-gray-500" />
        <span className="text-gray-600 font-medium">创建家庭</span>
      </motion.div>
    </div>
  )

  return (
    <>
      <motion.div
        whileTap={{ scale: 0.95 }}
        onClick={() => setDrawerOpen(true)}
        className="flex items-center gap-1 cursor-pointer"
      >
        <span className="text-lg font-semibold text-gray-800">
          {currentFamily?.name || '请选择家庭'}
        </span>
        <ChevronDown size={18} className="text-gray-500" />
      </motion.div>

      <Drawer
        isOpen={drawerOpen}
        onClose={() => {
          setDrawerOpen(false)
          setCreateMode(false)
        }}
        title={createMode ? '创建家庭' : '选择家庭'}
        height="h-4/5"
      >
        <AnimatePresence mode="wait">
          {createMode ? (
            <motion.div
              key="create"
              initial={{ opacity: 0, x: 20 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: -20 }}
            >
              {renderCreateForm()}
            </motion.div>
          ) : (
            <motion.div
              key="list"
              initial={{ opacity: 0, x: 20 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: -20 }}
            >
              {renderFamilyList()}
            </motion.div>
          )}
        </AnimatePresence>
      </Drawer>
    </>
  )
}

export default FamilySelector
