import { motion } from 'framer-motion'

const Card = ({
  children,
  className = '',
  padding = 'p-4',
  hover = false,
  onClick,
  ...props
}) => {
  return (
    <motion.div
      whileHover={hover ? { y: -2, boxShadow: '0 8px 24px rgba(0, 0, 0, 0.12)' } : undefined}
      onClick={onClick}
      className={`
        bg-white rounded-card shadow-card
        ${padding}
        ${hover ? 'cursor-pointer transition-shadow' : ''}
        ${className}
      `}
      {...props}
    >
      {children}
    </motion.div>
  )
}

export default Card
