import { useState } from 'react'
import { motion } from 'framer-motion'
import { Bell, Mic, Phone, ChevronRight } from 'lucide-react'
import Card from '../components/common/Card'
import IntercomDialog from './IntercomDialog'

const Function = ({ onNavigate }) => {
  const [showIntercom, setShowIntercom] = useState(false)

  const menuItems = [
    {
      id: 'medication',
      label: '用药提醒',
      desc: '设置药品提醒时间和语音',
      icon: Bell,
      iconBg: 'bg-blue-50',
      iconColor: 'text-blue-500',
    },
    {
      id: 'dialect',
      label: '方言呼救',
      desc: '录制方言呼救语音',
      icon: Mic,
      iconBg: 'bg-orange-50',
      iconColor: 'text-orange-500',
    },
    {
      id: 'intercom',
      label: '双向对讲',
      desc: '与设备进行语音对讲',
      icon: Phone,
      iconBg: 'bg-green-50',
      iconColor: 'text-green-500',
    },
  ]

  return (
    <div className="min-h-screen bg-bg pt-12 pb-16">
      <div className="px-4 py-4">
        <div className="space-y-3">
          {menuItems.map((item, index) => {
            const Icon = item.icon
            return (
              <motion.div
                key={item.id}
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: index * 0.1 }}
              >
                <Card className="p-0 overflow-hidden">
                  <motion.button
                    whileTap={{ scale: 0.98 }}
                    onClick={() => item.id === 'intercom' ? setShowIntercom(true) : onNavigate?.(item.id)}
                    className="w-full flex items-center gap-3 p-4 text-left"
                  >
                    <div className={`w-12 h-12 ${item.iconBg} rounded-xl flex items-center justify-center flex-shrink-0`}>
                      <Icon size={22} className={item.iconColor} />
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="font-medium text-gray-800">{item.label}</p>
                      <p className="text-sm text-gray-500 mt-0.5">{item.desc}</p>
                    </div>
                    <ChevronRight size={20} className="text-gray-300 flex-shrink-0" />
                  </motion.button>
                </Card>
              </motion.div>
            )
          })}
        </div>
      </div>

      <IntercomDialog
        isOpen={showIntercom}
        onClose={() => setShowIntercom(false)}
      />
    </div>
  )
}

export default Function